-- =============================================================================
-- Studuel — Migration 575 : SPORT Tle — LE CAHIER D'EXERCICES ET LES CONTRÔLES BLANCS
-- de la culture sportive (14/10/2026, docs/CADRAGE-SPORT.md). Deux parties générées,
-- collées à la suite : le cahier (scripts/exercices-sql.ts) puis les contrôles
-- (scripts/controles-sql.ts). À exécuter APRÈS la 568 (les chapitres doivent exister :
-- une ligne dont le chapitre manque est sautée, pas insérée).
-- =============================================================================

-- =============================================================================
-- 575 — LE CAHIER D'EXERCICES DE TLE
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 575 --niveau Tle --fichiers sport.culture > supabase/contenu/575_exercices_tle.sql
--
-- 30 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (0/0/5 gemmes depuis la 557, 20/35/50 XP), réglables ensuite en base.
--
--   sport.culture           30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"La saison d’Anaïs","competence":"lire-tableau","situation":"Anaïs, 17 ans, nage en club et vise les championnats de France. Son entraîneur a découpé sa saison en quatre périodes et lui a remis ce tableau. Lis-le ligne par ligne.","documents":[{"id":"saison","type":"tableau","titre":"La saison d’Anaïs, période par période","source":"Programme écrit pour l’exercice.","colonnes":["Période","Durée","Volume par semaine","Intensité"],"lignes":[["Préparation générale","10 semaines","45 km","faible à moyenne"],["Préparation spécifique","10 semaines","38 km","moyenne à élevée"],["Compétition","8 semaines","30 km","élevée"],["Transition","4 semaines","10 km","très faible"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne la **durée** de la préparation spécifique.","aide":"Repère la ligne « Préparation spécifique », puis la colonne « Durée ».","type":"zone","document":"saison","multiple":false},{"enonce":"Combien de semaines dure la saison d’Anaïs en tout ?","aide":"Additionne les durées des quatre périodes.","type":"nombre","unite":"semaines"},{"enonce":"Pourquoi la période de transition affiche-t-elle un volume de seulement 10 km et une intensité très faible ?","aide":"Regarde où se place la transition : après la compétition, avant la nouvelle saison.","type":"choix","options":[{"id":"a","texte":"Parce qu’Anaïs ne sait plus nager"},{"id":"b","texte":"Parce que le club n’a plus de piscine disponible"},{"id":"c","texte":"Pour souffler et se refaire une santé après la saison avant de repartir"},{"id":"d","texte":"Pour préparer son pic de forme de la semaine suivante"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La préparation spécifique dure **10 semaines** : le travail se rapproche du sport pratiqué et l’intensité monte."},{"cle":{"type":"nombre","valeur":32,"tolerance":0},"affichage":"32 semaines","explication":"10 + 10 + 8 + 4 = **32 semaines**. C’est le macrocycle : la saison entière, dessinée autour de la compétition."},{"cle":{"type":"choix","ids":["c"]},"explication":"La transition est un **repos actif** : on récupère du corps et de la tête avant de reconstruire. Sans elle, la saison suivante démarre sur de la fatigue."}]$ex$::jsonb),
  ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Trois semaines dures, une légère","competence":"lire-graphique","situation":"Tom prépare un marathon. Son entraîneur applique la règle « trois semaines dures pour une semaine légère ». Voici ses heures d’entraînement, semaine après semaine, sur trois mésocycles.","documents":[{"id":"charge","type":"graphique","forme":"barres","titre":"Heures d’entraînement par semaine","source":"Chiffres imaginés pour l’exercice.","categories":["S1","S2","S3","S4","S5","S6","S7","S8","S9","S10","S11","S12"],"series":[{"nom":"Heures par semaine","valeurs":[6,7,8,4,7,8,9,5,8,9,10,5],"teinte":"violet"}],"axeY":{"titre":"Heures","min":0,"max":12,"pas":2},"axeX":{"titre":"Semaine"},"valeurs":false}],"questions":[{"enonce":"Touche les **trois semaines de décharge** du plan.","aide":"Une décharge est une semaine nettement plus légère que celles qui l’entourent : cherche les creux.","type":"zone","document":"charge","multiple":true},{"enonce":"Combien d’heures Tom s’entraîne-t-il pendant le **premier mésocycle** (S1 à S4) ?","aide":"Additionne les quatre premières barres : 6, 7, 8 et la dernière.","type":"nombre","unite":"h"},{"enonce":"De combien de pour cent le volume baisse-t-il entre S3 et S4 ?","aide":"Calcule la baisse (S3 − S4), puis rapporte-la à S3.","type":"nombre","unite":"%"},{"enonce":"Tom saute la décharge de S8 « pour gagner du temps » et s’entraîne 9 heures. Que risque-t-il ?","aide":"Pense à ce que fait le corps pendant une semaine légère : il encaisse ou il se reconstruit ?","type":"choix","options":[{"id":"a","texte":"De perdre toute sa condition physique en une semaine"},{"id":"b","texte":"Rien : la décharge n’a aucun effet"},{"id":"c","texte":"De progresser deux fois plus vite"},{"id":"d","texte":"D’empiler de la fatigue sans la transformer en progrès"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3","k7","k11"]},"explication":"Les semaines **S4, S8 et S12** sont les décharges : 4, 5 et 5 heures. Elles laissent le corps transformer la fatigue en progrès."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 h","explication":"6 + 7 + 8 + 4 = **25 heures**. Le mésocycle dure quatre semaines, dont trois dures et une légère."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 %","explication":"De 8 h à 4 h, c’est une baisse de 4 h sur 8 h : **50 %**. Une vraie décharge est franche, pas une petite pause."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le corps progresse quand il encaisse une charge **puis récupère**. Sans décharge, la fatigue s’accumule : c’est le chemin vers le surentraînement."}]$ex$::jsonb),
  ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Deux affûtages, un seul bon","competence":"raisonner","situation":"Chloé et Mehdi, deux nageurs du même club, préparent les championnats de France. Leur entraîneur a gardé la règle de l’affûtage : réduire le volume de 40 à 60 % en gardant l’intensité. Un seul des deux plans la respecte.","documents":[{"id":"plan-chloe","type":"tableau","titre":"Plan de Chloé","source":"Programmes écrits pour l’exercice.","colonnes":["Semaine","Volume","Intensité des séries rapides"],"lignes":[["Avant l’affûtage","60 km","100 % de l’allure course"],["Semaine −3","42 km","100 % de l’allure course"],["Semaine −2","30 km","100 % de l’allure course"],["Semaine −1","24 km","100 % de l’allure course"]],"enteteLignes":true},{"id":"plan-mehdi","type":"tableau","titre":"Plan de Mehdi","source":"Programmes écrits pour l’exercice.","colonnes":["Semaine","Volume","Intensité des séries rapides"],"lignes":[["Avant l’affûtage","60 km","100 % de l’allure course"],["Semaine −3","30 km","80 % de l’allure course"],["Semaine −2","15 km","60 % de l’allure course"],["Semaine −1","6 km","40 % de l’allure course"]],"enteteLignes":true}],"questions":[{"enonce":"De combien de pour cent le volume de **Chloé** baisse-t-il entre « avant l’affûtage » et la semaine −1 ?","aide":"La baisse est 60 − 24 ; rapporte-la au volume de départ, 60 km.","type":"nombre","unite":"%"},{"enonce":"Touche, dans le plan de Mehdi, la case qui montre l’**intensité la plus basse**.","aide":"Parcours la dernière colonne : l’intensité diminue à chaque ligne.","type":"zone","document":"plan-mehdi","multiple":false},{"enonce":"Quel plan respecte la règle de l’affûtage, et pourquoi ?","aide":"La règle a deux volets. Vérifie-les un par un dans chaque tableau.","type":"choix","options":[{"id":"a","texte":"Celui de Mehdi : plus on se repose, meilleur on est"},{"id":"b","texte":"Celui de Chloé : le volume baisse mais l’intensité reste à 100 %"},{"id":"c","texte":"Aucun : un affûtage ne peut pas durer trois semaines"},{"id":"d","texte":"Les deux : seul le volume compte"}],"multiple":false},{"enonce":"Complète la règle de l’affûtage.","aide":"Reprends ce que fait Chloé : que devient le volume ? et la vitesse des séries ?","type":"trous","segments":["On ",0," le volume d’environ 40 à 60 % mais on garde l’",1,"."],"banque":["réduit","durée","augmente","repos","intensité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 %","explication":"60 − 24 = 36 km de moins, soit 36 sur 60 = **60 %**. C’est le haut de la fourchette de 40 à 60 %."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"À la semaine −1, Mehdi ne nage plus qu’à **40 %** de l’allure course. Il a tout baissé : volume ET intensité."},{"cle":{"type":"choix","ids":["b"]},"explication":"Chloé baisse le **volume** et garde l’**intensité** : son corps efface la fatigue mais garde les gestes rapides. Mehdi perd sa fraîcheur de vitesse en baissant tout."},{"cle":{"type":"trous","trous":[["reduit","diminue","baisse"],["intensite"]]},"affichage":"réduit · intensité","explication":"On **réduit** le volume et on garde l’**intensité**. Baisser tout, c’est se désentraîner : le jour J, les jambes sont fraîches mais lentes."}]$ex$::jsonb),
  ('c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"La fiche de Sofiane","competence":"lire-tableau","situation":"Sofiane, 17 ans, court le 5 000 m. Son entraîneur veut régler ses allures avec la formule de Karvonen. Il a noté deux mesures sur sa fiche.","documents":[{"id":"fiche-sofiane","type":"fiche","modele":"affiche","entete":"FICHE DE SOFIANE","sousTitre":"Mesures de la saison — chiffres imaginés pour l’exercice","emoji":"🫀","lignes":[{"texte":"FC de repos (au réveil) : 55 battements par minute","id":"z1"},{"texte":"FC max (test de terrain) : 195 battements par minute","id":"z2"},{"texte":"Test de Cooper (12 min) : 3 100 m","id":"z3"}],"pied":"Formule : FC cible = FC repos + % × (FC max − FC repos)","teinte":"violet"}],"questions":[{"enonce":"Touche la ligne qui donne la **FC de repos** de Sofiane.","aide":"La FC de repos se mesure au calme, au réveil.","type":"zone","document":"fiche-sofiane","multiple":false},{"enonce":"Calcule la **FC de réserve** de Sofiane (FC max − FC de repos).","aide":"Soustrais la FC de repos à la FC max.","type":"nombre","unite":"bpm"},{"enonce":"Quelle est sa **FC cible** pour une intensité de 70 % ? Utilise la formule du pied de la fiche.","aide":"55 + 0,7 × 140 : commence par la multiplication.","type":"nombre","unite":"bpm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La FC de repos de Sofiane est de **55 battements par minute**, relevée au réveil. Elle baisse avec l’entraînement."},{"cle":{"type":"nombre","valeur":140,"tolerance":0},"affichage":"140 bpm","explication":"195 − 55 = **140 bpm**. C’est la marge dont dispose son cœur entre le calme et l’effort maximal."},{"cle":{"type":"nombre","valeur":153,"tolerance":0},"affichage":"153 bpm","explication":"0,7 × 140 = 98, puis 55 + 98 = **153 bpm**. Sans la FC de repos, on se tromperait de plusieurs battements."}]$ex$::jsonb),
  ('c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Une séance de fractionné","competence":"lire-graphique","situation":"Lina, handballeuse de 17 ans, fait une séance de fractionné : des efforts courts suivis de récupérations. Sa montre a enregistré sa fréquence cardiaque. Sa FC max est de 190 bpm.","documents":[{"id":"fc","type":"graphique","forme":"courbe","titre":"Fréquence cardiaque de Lina pendant la séance","source":"Chiffres imaginés pour l’exercice.","categories":["0","5","10","15","20","25","30"],"series":[{"nom":"FC (bpm)","valeurs":[95,140,175,120,178,125,100],"teinte":"corail"}],"axeY":{"titre":"Battements par minute","min":80,"max":200,"pas":20},"axeX":{"titre":"Minutes"},"valeurs":false},{"id":"zones","type":"tableau","titre":"Les zones d’intensité du carnet","source":"Repères écrits pour l’exercice, en pourcentage de la FC max.","colonnes":["Zone","Pourcentage de la FC max","Effort"],"lignes":[["1","moins de 60 %","très facile, récupération"],["2","60 % à 70 %","facile, endurance"],["3","70 % à 80 %","soutenu"],["4","80 % à 90 %","dur"],["5","plus de 90 %","maximal, quelques minutes au plus"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la **minute** où la FC de Lina est la plus haute.","aide":"Compare les deux sommets de la courbe : lequel monte un peu plus haut ?","type":"zone","document":"fc","multiple":false},{"enonce":"À quel pourcentage de sa FC max Lina est-elle à son sommet (178 bpm) ? Arrondis à l’unité.","aide":"Divise 178 par 190, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"À la minute 5, Lina est à 140 bpm. Dans quelle zone se trouve-t-elle ?","aide":"Calcule 140 ÷ 190, puis cherche la ligne du tableau qui contient ce pourcentage.","type":"choix","options":[{"id":"a","texte":"Zone 1"},{"id":"b","texte":"Zone 2"},{"id":"c","texte":"Zone 3"},{"id":"d","texte":"Zone 4"}],"multiple":false},{"enonce":"Entre la minute 10 et la minute 15, de combien de battements par minute la FC de Lina **baisse-t-elle** ?","aide":"Lis la FC à ces deux minutes sur la courbe, puis soustrais.","type":"nombre","unite":"bpm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"À la minute **20**, Lina atteint 178 bpm : c’est son maximum de la séance, un peu au-dessus des 175 bpm de la minute 10."},{"cle":{"type":"nombre","valeur":94,"tolerance":0},"affichage":"94 %","explication":"178 ÷ 190 ≈ 0,937, soit **94 %** de la FC max : c’est la zone 5, celle des efforts maximaux de courte durée."},{"cle":{"type":"choix","ids":["c"]},"explication":"140 ÷ 190 ≈ 74 % : c’est la **zone 3**, entre 70 % et 80 % de la FC max, un effort soutenu."},{"cle":{"type":"nombre","valeur":55,"tolerance":0},"affichage":"55 bpm","explication":"175 − 120 = **55 bpm** perdus en cinq minutes : une bonne récupération entre deux efforts est le signe d’un cœur en forme."}]$ex$::jsonb),
  ('c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Une semaine de carnet commentée","competence":"analyser-document","situation":"Maëlys, 17 ans, tient son carnet d’entraînement. Elle note la durée de chaque séance et son ressenti sur l’échelle de Borg (RPE, de 1 à 10). Son préparateur compare ensuite cette semaine aux précédentes.","documents":[{"id":"carnet","type":"tableau","titre":"Le carnet de Maëlys, semaine 4","source":"Chiffres imaginés pour l’exercice.","colonnes":["Jour","Séance","Durée (min)","RPE"],"lignes":[["Lundi","Footing",60,4],["Mardi","Fractionné",50,8],["Jeudi","Renforcement",45,6],["Samedi","Sortie longue",90,5],["Dimanche","Repos","—","—"]],"enteteLignes":true},{"id":"historique","type":"tableau","titre":"Les charges des semaines précédentes","source":"Repère du préparateur, écrit pour l’exercice : au-delà de 1,3 fois la moyenne des trois semaines précédentes, la hausse est trop brutale.","colonnes":["Semaine","Charge (unités)"],"lignes":[["Semaine 1",900],["Semaine 2",1000],["Semaine 3",1100]],"enteteLignes":true}],"questions":[{"enonce":"Touche la **séance** dont la charge (RPE × durée) est la plus élevée.","aide":"Calcule la charge de chaque séance. Attention : la plus longue n’est pas forcément la plus lourde.","type":"zone","document":"carnet","multiple":false},{"enonce":"Calcule la **charge totale** de la semaine 4 (somme des RPE × durée).","aide":"4 × 60 ; 8 × 50 ; 6 × 45 ; 5 × 90. Additionne ensuite les quatre résultats.","type":"nombre","unite":"unités"},{"enonce":"Calcule le **ratio** entre la charge de la semaine 4 et la moyenne des trois semaines précédentes.","aide":"La moyenne des semaines 1 à 3 est (900 + 1 000 + 1 100) ÷ 3. Puis divise 1 360 par cette moyenne.","type":"nombre"},{"enonce":"Que doit conclure le préparateur, et que propose-t-il ?","aide":"Compare ton ratio au repère de 1,3 donné sous le deuxième tableau.","type":"choix","options":[{"id":"a","texte":"Tout va bien : plus la charge monte, plus on progresse"},{"id":"b","texte":"La séance de fractionné est inutile et doit disparaître"},{"id":"c","texte":"La hausse dépasse 1,3 : il vaut mieux alléger la semaine suivante pour éviter la blessure"},{"id":"d","texte":"Maëlys doit supprimer son jour de repos"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"Footing 240, fractionné 400, renforcement 270, sortie longue 5 × 90 = **450** : la sortie longue est la séance la plus lourde de la semaine."},{"cle":{"type":"nombre","valeur":1360,"tolerance":0},"affichage":"1360 unités","explication":"240 + 400 + 270 + 450 = **1 360 unités**. Le dimanche de repos ne compte pas : charge nulle."},{"cle":{"type":"nombre","valeur":1.36,"tolerance":0.01},"affichage":"1,36","explication":"La moyenne vaut 1 000, donc 1 360 ÷ 1 000 = **1,36**. C’est le ratio aigu/chronique : la semaine en cours rapportée aux semaines habituelles."},{"cle":{"type":"choix","ids":["c"]},"explication":"Avec **1,36**, la charge a grimpé trop vite : c’est le profil de risque de blessure. Mesurer ne suffit pas, il faut **interpréter** : ici, alléger."}]$ex$::jsonb),
  ('58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"La courbe du stress","competence":"lire-graphique","situation":"Un psychologue du sport présente aux lycéens la courbe de Yerkes-Dodson. Elle relie le niveau d’activation (stress, excitation) à la qualité de la performance.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Performance selon le niveau d’activation","source":"Courbe schématique, chiffres imaginés pour l’exercice.","categories":["1","2","3","4","5","6"],"series":[{"nom":"Performance (sur 100)","valeurs":[25,55,85,95,70,30],"teinte":"violet"}],"axeY":{"titre":"Performance (sur 100)","min":0,"max":100,"pas":20},"axeX":{"titre":"Niveau d’activation (1 = très bas, 6 = très haut)"},"valeurs":false}],"questions":[{"enonce":"Touche le **niveau d’activation** où la performance est la meilleure.","aide":"Cherche le sommet de la courbe.","type":"zone","document":"courbe","multiple":false},{"enonce":"Quelle est la performance quand l’activation est au niveau 6 ?","aide":"Lis la valeur de la courbe tout à droite.","type":"nombre"},{"enonce":"Que montre la forme de cette courbe, dite « en U inversé » ?","aide":"Compare les deux extrémités de la courbe avec son sommet.","type":"choix","options":[{"id":"a","texte":"La performance est meilleure à un niveau d’activation intermédiaire, et baisse s’il est trop bas ou trop haut"},{"id":"b","texte":"Le stress n’a aucun effet sur la performance"},{"id":"c","texte":"Il faut supprimer complètement le stress"},{"id":"d","texte":"Plus on est stressé, mieux on performe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Le sommet est au niveau **4** (95 sur 100) : c’est l’activation optimale, ni trop basse ni trop haute."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30","explication":"Au niveau 6, la performance tombe à **30 sur 100** : trop de stress crispe les gestes et fait commettre des erreurs."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le stress n’est pas l’ennemi : il faut trouver son niveau d’activation **optimal**. Trop bas, on est mou ; trop haut, on se crispe."}]$ex$::jsonb),
  ('58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Avant le service de Lola","competence":"analyser-document","situation":"Lola, 17 ans, est joueuse de volley. Elle perdait ses moyens sur le service quand le score était serré. Elle en parle avec son entraîneur dans une conversation écrite pour l’exercice.","documents":[{"id":"echange","type":"dialogue","modele":"sms","titre":"Conversation avec l’entraîneur","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Entraîneur","emoji":"🧑‍🏫","cote":"gauche"},{"nom":"Lola","emoji":"🏐","cote":"droite"}],"repliques":[{"qui":"Entraîneur","texte":"Avant ton service, qu’est-ce que tu fais maintenant ?"},{"qui":"Lola","texte":"Je rebondis trois fois la balle, je respire lentement, puis je regarde ma cible. Toujours dans cet ordre."},{"qui":"Entraîneur","texte":"Et dans ta tête ?"},{"qui":"Lola","texte":"Avant, je me disais « Tout le monde me regarde, je vais rater ». Maintenant je me dis « Une action à la fois »."},{"qui":"Entraîneur","texte":"Bien. Dans le vestiaire, fais cinq minutes de cohérence cardiaque : inspire cinq secondes, expire cinq secondes."}]}],"questions":[{"enonce":"Touche les trois mots qui désignent les **gestes de la routine** de Lola.","aide":"Cherche les verbes que Lola enchaîne toujours dans le même ordre avant de servir.","type":"zone","document":"echange","multiple":true},{"enonce":"Range ces phrases de dialogue interne : aident-elles ou nuisent-elles ?","aide":"Une phrase aide quand elle ramène à l’action présente. Elle nuit quand elle annonce l’échec ou grossit l’enjeu.","type":"categories","categories":[{"id":"c0","texte":"Aide à rester concentré"},{"id":"c1","texte":"Nuit à la performance"}],"items":[{"id":"i0","texte":"Si je perds ce point, c’est fini"},{"id":"i1","texte":"Tout le monde me regarde"},{"id":"i2","texte":"Respire, puis sers"},{"id":"i3","texte":"Regarde ta cible"},{"id":"i4","texte":"Une action à la fois"},{"id":"i5","texte":"Je vais rater"}]},{"enonce":"Cinq minutes de cohérence cardiaque, à six respirations par minute : combien de respirations complètes Lola fait-elle ?","aide":"Une respiration complète = une inspiration et une expiration de cinq secondes chacune. Combien en une minute ?","type":"nombre"},{"enonce":"Pourquoi la routine d’avant-service aide-t-elle Lola sous pression ?","aide":"Qu’est-ce qui occupe l’esprit de Lola pendant sa routine ?","type":"choix","options":[{"id":"a","texte":"Elle ancre son attention sur des gestes qu’elle maîtrise, au lieu de ses craintes"},{"id":"b","texte":"Elle supprime complètement le stress"},{"id":"c","texte":"Elle fait gagner du temps au match"},{"id":"d","texte":"Elle trompe l’adversaire sur l’endroit du service"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m16","m20"]},"explication":"Lola **rebondit**, **respire**, **regarde** : trois gestes répétés à l’identique. La routine ancre l’attention et empêche les pensées de vagabonder."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"Le dialogue interne compte. « Une action à la fois » ramène au geste ; « Je vais rater » installe l’échec."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30","explication":"5 s + 5 s = 10 s par respiration, soit 6 par minute. En 5 minutes : 6 × 5 = **30 respirations**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La routine donne à l’attention un **point d’appui contrôlable**. Elle ne supprime pas le stress : elle empêche les pensées de s’emballer."}]$ex$::jsonb),
  ('58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Trois athlètes, une courbe","competence":"observer-schema","situation":"Avant une compétition, trois athlètes décrivent leurs sensations. Le psychologue du sport place chacun sur la courbe de Yerkes-Dodson (points A, B et C) pour comprendre ce qui se passe.","documents":[{"id":"yd","type":"schema","titre":"Performance et activation","source":"Schéma simplifié écrit pour l’exercice.","largeur":320,"hauteur":230,"elements":[{"forme":"ligne","de":[40,190],"a":[300,190],"fleche":"fin","teinte":"encre"},{"forme":"ligne","de":[40,190],"a":[40,25],"fleche":"fin","teinte":"encre"},{"forme":"chemin","d":"M 50 180 Q 170 -40 290 180","teinte":"violet"},{"forme":"cercle","cx":86,"cy":124,"r":13,"teinte":"jaune","motif":"plein","texte":"A","id":"z1","zone":true},{"forme":"cercle","cx":170,"cy":70,"r":13,"teinte":"jaune","motif":"plein","texte":"B","id":"z2","zone":true},{"forme":"cercle","cx":254,"cy":124,"r":13,"teinte":"jaune","motif":"plein","texte":"C","id":"z3","zone":true},{"forme":"texte","x":170,"y":218,"texte":"Niveau d’activation","taille":"petit","ancre":"milieu"},{"forme":"texte","x":40,"y":16,"texte":"Performance","taille":"petit","ancre":"milieu"}]},{"id":"athletes","type":"tableau","titre":"Ce que ressentent les trois athlètes","source":"Situations imaginées pour l’exercice.","colonnes":["Athlète","Ce qu’il ressent juste avant le départ"],"lignes":[["Hugo, sprinter","Jambes molles, bâille, aucune envie de se battre"],["Inès, tir à l’arc","Mains qui tremblent, pensées qui s’emballent, n’arrive plus à viser"],["Maya, judo","Concentrée, pleine d’énergie, gestes précis"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le point de la courbe qui correspond à **Hugo**.","aide":"Hugo manque d’activation. Où se trouvent les niveaux trop bas sur la courbe ?","type":"zone","document":"yd","multiple":false},{"enonce":"Touche le point qui correspond à **Inès**.","aide":"Les tremblements et les pensées qui s’emballent signalent un excès d’activation.","type":"zone","document":"yd","multiple":false},{"enonce":"Quel conseil convient le mieux à Inès, juste avant son tir ?","aide":"Inès doit redescendre vers le sommet de la courbe. Quel outil agit directement sur le stress ?","type":"choix","options":[{"id":"a","texte":"Respirer lentement (cohérence cardiaque) et se fixer une consigne simple"},{"id":"b","texte":"Se faire peur avec le pire scénario pour se motiver"},{"id":"c","texte":"Courir pour s’exciter encore plus"},{"id":"d","texte":"Surveiller chaque détail de son geste en pensée"}],"multiple":false},{"enonce":"Complète l’idée centrale de la courbe de Yerkes-Dodson.","aide":"Maya, au point B, est le modèle : ni molle, ni crispée.","type":"trous","segments":["La performance est maximale à une activation ",0,", ni ",1," de stress, ni trop."],"banque":["trop","pas assez","maximale","nulle","optimale"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Hugo est trop peu activé : il est au point **A**, à gauche. Mou, sans envie, il performera en dessous de son niveau."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Inès est trop activée : elle est au point **C**, à droite. Tension et gestes crispés font commettre des erreurs."},{"cle":{"type":"choix","ids":["a"]},"explication":"La respiration est un levier direct sur le stress, et une consigne simple évite le « choke », quand on surveille son propre geste au lieu de lui faire confiance."},{"cle":{"type":"trous","trous":[["optimale","intermediaire"],["pas assez","trop peu"]]},"affichage":"optimale · pas assez","explication":"Maya est au point B, au sommet : l’activation est **optimale**. Hugo n’a **pas assez** de stress, Inès en a trop."}]$ex$::jsonb),
  ('3e6141f6-e362-5765-a122-b8532787e93a'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Le carnet de Léo","competence":"lire-tableau","situation":"Léo, 17 ans, s’entraîne six fois par semaine. Depuis février, ses chronos stagnent. Il a noté dans son carnet trois chiffres chaque semaine.","documents":[{"id":"carnet-leo","type":"tableau","titre":"Le carnet de Léo","source":"Chiffres imaginés pour l’exercice.","colonnes":["Semaine","FC de repos (bpm)","Sommeil moyen","RPE d’une séance type"],"lignes":[["Semaine 1",55,"8 h 30",6],["Semaine 2",58,"7 h 45",7],["Semaine 3",62,"7 h",8],["Semaine 4",65,"6 h",9]],"enteteLignes":true}],"questions":[{"enonce":"Touche la **FC de repos** de la semaine 4.","aide":"Cherche la ligne « Semaine 4 », puis la colonne de la FC de repos.","type":"zone","document":"carnet-leo","multiple":false},{"enonce":"De combien de battements par minute la FC de repos de Léo a-t-elle augmenté entre la semaine 1 et la semaine 4 ?","aide":"Soustrais la valeur de la semaine 1 à celle de la semaine 4.","type":"nombre","unite":"bpm"},{"enonce":"Que racontent ensemble ces trois colonnes ?","aide":"Regarde le sens de variation de chaque colonne, de la semaine 1 à la semaine 4.","type":"choix","options":[{"id":"a","texte":"Un excès de repos : Léo ne s’entraîne pas assez"},{"id":"b","texte":"Une progression normale : Léo devient plus fort"},{"id":"c","texte":"Les signes d’un surentraînement qui s’installe : FC de repos en hausse, sommeil en baisse, effort ressenti plus dur"},{"id":"d","texte":"Rien : trois chiffres ne prouvent jamais rien"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"En semaine 4, la FC de repos de Léo est de **65 bpm**."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 bpm","explication":"65 − 55 = **10 bpm** de plus. Une FC de repos qui grimpe au réveil est un signe d’alerte."},{"cle":{"type":"choix","ids":["c"]},"explication":"Plusieurs signes concordants : le carnet **lance l’alerte** avant que Léo ne sente la fatigue. Il faut alléger et en parler à un médecin ou à un entraîneur."}]$ex$::jsonb),
  ('3e6141f6-e362-5765-a122-b8532787e93a'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Quand les chronos reculent","competence":"lire-graphique","situation":"Chaque mois, Noémie, 17 ans, passe le test de Cooper (la distance parcourue en 12 minutes). Elle s’entraîne six fois par semaine depuis septembre, sans jamais lever le pied.","documents":[{"id":"cooper","type":"graphique","forme":"courbe","titre":"Distance au test de Cooper, mois après mois","source":"Chiffres imaginés pour l’exercice.","categories":["Oct.","Nov.","Déc.","Janv.","Févr.","Mars","Avr."],"series":[{"nom":"Distance en 12 min","valeurs":[2800,2900,3000,3050,3000,2900,2800],"teinte":"turquoise"}],"axeY":{"titre":"Distance (m)","min":2600,"max":3200,"pas":100},"axeX":{"titre":"Mois"},"valeurs":false}],"questions":[{"enonce":"Touche le **mois** du meilleur résultat de Noémie.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"cooper","multiple":false},{"enonce":"De combien de mètres la distance a-t-elle diminué entre janvier et avril ?","aide":"Lis les deux valeurs sur la courbe, puis soustrais.","type":"nombre","unite":"m"},{"enonce":"Relie chaque situation à l’état qui lui correspond.","aide":"La durée de la fatigue décide de l’état : quelques heures, quelques jours ou des semaines.","type":"association","gauche":[{"id":"g0","texte":"Courbatures après un gros match, disparues en une journée"},{"id":"g1","texte":"Jambes lourdes depuis cinq jours"},{"id":"g2","texte":"Chronos en baisse depuis deux mois malgré six séances par semaine"}],"droite":[{"id":"d0","texte":"Surmenage"},{"id":"d1","texte":"Fatigue normale"},{"id":"d2","texte":"Surentraînement"}]},{"enonce":"Noémie pense : « Ma courbe baisse, donc je n’en fais pas assez. » Que lui répondre ?","aide":"La baisse s’observe alors que la charge n’a pas bougé. Qu’est-ce qui manque dans son plan ?","type":"choix","options":[{"id":"a","texte":"Ce n’est pas grave, la courbe remontera toute seule sans rien changer"},{"id":"b","texte":"Il faut arrêter de tenir le carnet"},{"id":"c","texte":"Elle a raison : il faut ajouter une séance"},{"id":"d","texte":"Au contraire : une performance qui baisse malgré le travail est un signe d’alerte, il faut alléger"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Son meilleur test est en **janvier** : 3 050 m."},{"cle":{"type":"nombre","valeur":250,"tolerance":0},"affichage":"250 m","explication":"3 050 − 2 800 = **250 m** perdus en trois mois, alors que l’entraînement n’a pas diminué."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**Quelques heures à un jour** : fatigue normale. **Quelques jours** : surmenage. **Des semaines, voire des mois** : surentraînement, comme la courbe de Noémie."},{"cle":{"type":"choix","ids":["d"]},"explication":"On progresse **pendant la récupération**, pas pendant l’effort. Ajouter une séance aggraverait le déséquilibre ; c’est une décharge et un avis médical qu’il lui faut."}]$ex$::jsonb),
  ('3e6141f6-e362-5765-a122-b8532787e93a'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Le journal de Camille","competence":"analyser-texte","situation":"Camille, 17 ans, joue au volley et passe le bac en juin. Elle tient un journal et un carnet. À toi de croiser les deux pour comprendre ce qui lui arrive.","documents":[{"id":"journal","type":"texte","genre":"recit","titre":"Le journal de Camille","auteur":"Texte écrit pour l’exercice","blocs":["Février. Je m’entraîne six fois par semaine depuis septembre, sans jamais lever le pied : je veux tout donner avant le bac.","Mars. Mes temps reculent alors que je m’entraîne davantage. Je suis irritable et j’ai enchaîné trois rhumes.","Avril. Je révise jusqu’à minuit, le téléphone sous l’oreiller. Je dors six heures par nuit."]},{"id":"carnet-camille","type":"tableau","titre":"Le carnet de Camille","source":"Chiffres imaginés pour l’exercice.","colonnes":["Mois","FC de repos (bpm)","Sommeil moyen","RPE d’une séance type"],"lignes":[["Septembre",52,"9 h",6],["Décembre",55,"8 h",6],["Mars",62,"6 h 30",8],["Avril",66,"6 h",9]],"enteteLignes":true}],"questions":[{"enonce":"Touche les trois mots du journal qui désignent des **signes d’alerte**.","aide":"Cherche ce qui montre que son corps et sa tête ne suivent plus : performance, humeur, santé.","type":"zone","document":"journal","multiple":true},{"enonce":"De combien de battements par minute sa FC de repos a-t-elle augmenté entre septembre et avril ?","aide":"Lis les deux valeurs dans le carnet et soustrais.","type":"nombre","unite":"bpm"},{"enonce":"Range ces éléments : causes du problème, ou signes d’alerte ?","aide":"Une cause explique pourquoi le déséquilibre arrive ; un signe est la conséquence qu’on observe.","type":"categories","categories":[{"id":"c0","texte":"Cause"},{"id":"c1","texte":"Signe d’alerte"}],"items":[{"id":"i0","texte":"Pas de semaine de décharge"},{"id":"i1","texte":"Chronos qui reculent"},{"id":"i2","texte":"Sommeil de six heures"},{"id":"i3","texte":"Stress du bac qui s’ajoute au sport"},{"id":"i4","texte":"Rhumes à répétition"},{"id":"i5","texte":"FC de repos qui monte"}]},{"enonce":"Quelle première mesure aura le plus d’effet pour Camille ?","aide":"Quel levier est « le plus puissant » selon le cours ?","type":"choix","options":[{"id":"a","texte":"Ajouter une séance de récupération active par jour"},{"id":"b","texte":"Se faire masser une fois par semaine"},{"id":"c","texte":"Alléger fortement sa charge et retrouver au moins 9 heures de sommeil"},{"id":"d","texte":"Prendre un bain froid après chaque séance"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m34","m40"]},"explication":"Des temps qui **reculent**, de l’**irritabilité**, des **rhumes** à répétition : trois signes classiques du surentraînement."},{"cle":{"type":"nombre","valeur":14,"tolerance":0},"affichage":"14 bpm","explication":"66 − 52 = **14 bpm**. Sa FC de repos a grimpé en même temps que son sommeil s’effondrait."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"Les **causes** : pas de décharge, peu de sommeil, stress scolaire. Les **signes** : performance en baisse, infections, FC de repos élevée."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **sommeil** est le premier outil de récupération, devant massages et bains froids (effet modeste). Avec une charge allégée, il traite les deux causes principales."}]$ex$::jsonb),
  ('475d747d-a507-5860-ad09-00a4423612c4'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Les repères de l’OMS","competence":"lire-tableau","situation":"Au CDI, un affichage rappelle les recommandations de l’Organisation mondiale de la santé. Tom, 16 ans, vient de noter qu’il bouge environ 35 minutes par jour.","documents":[{"id":"oms","type":"tableau","titre":"Les recommandations d’activité physique","source":"D’après les repères de l’OMS.","colonnes":["Public","Quantité recommandée","Intensité"],"lignes":[["Enfants et jeunes de 5 à 17 ans","60 minutes par jour","modérée à soutenue"],["Adultes","150 à 300 minutes par semaine","modérée"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne la quantité recommandée pour **Tom**, 16 ans.","aide":"Tom a entre 5 et 17 ans : quelle ligne du tableau le concerne ?","type":"zone","document":"oms","multiple":false},{"enonce":"Combien de minutes d’activité par **semaine** cela représente-t-il pour un jeune ?","aide":"60 minutes par jour, pendant sept jours.","type":"nombre","unite":"min"},{"enonce":"Combien de minutes par jour **manque-t-il** à Tom pour atteindre la recommandation ?","aide":"Soustrais ce qu’il fait déjà de ce qui est recommandé.","type":"nombre","unite":"min"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Pour les 5-17 ans, l’OMS recommande **60 minutes par jour**."},{"cle":{"type":"nombre","valeur":420,"tolerance":0},"affichage":"420 min","explication":"60 × 7 = **420 minutes** par semaine, soit 7 heures."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 min","explication":"60 − 35 = **25 minutes** par jour. Bouger un peu vaut mieux que ne pas bouger, mais bouger plus apporte davantage."}]$ex$::jsonb),
  ('475d747d-a507-5860-ad09-00a4423612c4'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Une journée assise","competence":"lire-graphique","situation":"Nour, 16 ans, fait une heure de sport tous les jours. Elle se croit donc « active ». Elle a pourtant relevé l’emploi du temps de sa journée de 24 heures.","documents":[{"id":"journee","type":"graphique","forme":"barres-h","titre":"Les 24 heures de Nour","source":"Chiffres imaginés pour l’exercice.","categories":["Sommeil","Cours (assise)","Écrans (assise)","Trajets en bus (assise)","Devoirs (assise)","Repas, temps libre debout","Sport","Marche"],"series":[{"nom":"Heures","valeurs":[9,6,3,1,1,2,1,1],"teinte":"ambre"}],"axeY":{"titre":"Heures","min":0,"max":10,"pas":2},"valeurs":true}],"questions":[{"enonce":"Touche la barre du temps que Nour consacre au **sport**.","aide":"Cherche le libellé « Sport » dans la liste.","type":"zone","document":"journee","multiple":false},{"enonce":"Combien d’heures Nour passe-t-elle **assise, éveillée** (cours, écrans, trajets, devoirs) ?","aide":"Additionne les quatre barres marquées « assise ».","type":"nombre","unite":"h"},{"enonce":"Que peut-on dire de la situation de Nour ?","aide":"Distingue deux notions : atteindre l’activité recommandée, et passer son temps assis.","type":"choix","options":[{"id":"a","texte":"Elle atteint le repère d’activité mais reste très sédentaire : les deux risques comptent"},{"id":"b","texte":"Elle est inactive, puisqu’elle passe plus de temps assise que debout"},{"id":"c","texte":"Elle n’a aucun risque, la sédentarité n’existe pas à son âge"},{"id":"d","texte":"Elle est en parfaite santé : une heure de sport efface tout"}],"multiple":false},{"enonce":"Complète la différence entre les deux notions.","aide":"Les deux mots se ressemblent : l’un parle du temps assis, l’autre du manque d’activité.","type":"trous","segments":["La ",0," désigne le temps passé assis ou allongé en étant éveillé ; l’",1," physique, c’est ne pas atteindre les niveaux d’activité recommandés."],"banque":["sédentarité","endurance","fatigue","inactivité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k6"]},"explication":"Nour fait **1 heure** de sport par jour : elle atteint tout juste le repère de 60 minutes."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 h","explication":"6 + 3 + 1 + 1 = **11 heures** assise. C’est de la sédentarité, même si Nour fait du sport."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’**inactivité** et la **sédentarité** sont deux problèmes distincts. Nour échappe à la première mais pas à la seconde."},{"cle":{"type":"trous","trous":[["sedentarite"],["inactivite"]]},"affichage":"sédentarité · inactivité","explication":"**Sédentarité** = temps assis ; **inactivité** = activité insuffisante. On peut faire une heure de sport et rester sédentaire."}]$ex$::jsonb),
  ('475d747d-a507-5860-ad09-00a4423612c4'::uuid, 3, 3, 5, 50, 5,
   $ex${"titre":"Une ordonnance pas comme les autres","competence":"se-reperer-temps","situation":"M. Garnier, 58 ans, est atteint d’un diabète de type 2. Son médecin ne lui prescrit pas seulement des médicaments : il lui prescrit du sport. Pour comprendre comment c’est possible, remonte le temps.","documents":[{"id":"frise-sante","type":"frise","titre":"Le sport au service de la santé","source":"Repères historiques.","debut":2015,"fin":2025,"pas":1,"evenements":[{"id":"z1","date":2016,"nom":"Loi"},{"id":"z2","date":2017,"nom":"Entrée en vigueur"},{"id":"z3","date":2019,"nom":"Maisons Sport-Santé"},{"id":"z4","date":2020,"nom":"Rapport ANSES"},{"id":"z5","date":2022,"nom":"30 min à l’école"},{"id":"z6","date":2024,"nom":"Grande cause"}]},{"id":"ordonnance","type":"fiche","modele":"affiche","entete":"ORDONNANCE","sousTitre":"Document imaginé pour l’exercice","emoji":"🩺","lignes":[{"texte":"Patient : M. Garnier, 58 ans","id":"z7"},{"texte":"Maladie de longue durée : diabète de type 2","id":"z8"},{"texte":"Prescription : activité physique adaptée","id":"z9"},{"texte":"3 séances de 45 minutes par semaine, en Maison Sport-Santé","id":"z10"}],"pied":"Cabinet du Dr Lefèvre","teinte":"turquoise"}],"questions":[{"enonce":"Touche l’événement de **2019**.","aide":"Place-toi sur la graduation 2019 de la frise et regarde ce qui y est rattaché.","type":"zone","document":"frise-sante","multiple":false},{"enonce":"Remets ces mesures dans l’ordre chronologique.","aide":"Sers-toi des dates de la frise : 2016, 2019, 2022, 2024.","type":"ordre","items":[{"id":"a","texte":"L’activité physique grande cause nationale"},{"id":"b","texte":"Les 30 minutes d’activité quotidienne à l’école"},{"id":"c","texte":"La création des Maisons Sport-Santé"},{"id":"d","texte":"La loi sur l’activité physique prescrite par le médecin"}]},{"enonce":"Combien d’années séparent la loi de 2016 de la déclaration « grande cause nationale » ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Touche la ligne de l’ordonnance qui **justifie** que le médecin ait le droit de prescrire du sport à M. Garnier.","aide":"La loi vise les personnes atteintes d’un certain type de maladie.","type":"zone","document":"ordonnance","multiple":false},{"enonce":"Que veut dire « activité physique **adaptée** » pour M. Garnier ?","aide":"Relis les mots « séances » et « Maison Sport-Santé » dans l’ordonnance.","type":"choix","options":[{"id":"a","texte":"Une activité identique à celle d’un sportif de haut niveau"},{"id":"b","texte":"Une activité dosée selon son état de santé, encadrée par des professionnels, pour qu’il progresse sans danger"},{"id":"c","texte":"Une activité si légère qu’elle ne sert à rien"},{"id":"d","texte":"Une activité qu’il choisit seul, sans suivi"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"En 2019 sont créées les **Maisons Sport-Santé**, qui accueillent ceux qui veulent se remettre au sport avec un accompagnement."},{"cle":{"type":"ordre","ids":["d","c","b","a"]},"explication":"Loi de **2016**, Maisons Sport-Santé en **2019**, 30 minutes à l’école en **2022**, grande cause nationale en **2024**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 ans","explication":"2024 − 2016 = **8 ans**. Le sport santé a pris sa place progressivement dans les politiques publiques."},{"cle":{"type":"zone","ids":["z8"]},"explication":"La loi permet de prescrire l’activité physique adaptée aux personnes atteintes d’une **maladie de longue durée**, comme le diabète de type 2."},{"cle":{"type":"choix","ids":["b"]},"explication":"« Adaptée » ne veut pas dire « allégée pour rien » : la séance est **dosée** pour que la personne progresse sans se mettre en danger."}]$ex$::jsonb),
  ('3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Le match du dimanche","competence":"analyser-texte","situation":"Un sociologue explique pourquoi un match de rugby, pourtant très physique, ne finit pas en bagarre générale. Lis son raisonnement, écrit pour l’exercice.","documents":[{"id":"rugby","type":"texte","genre":"article","titre":"Un jeu violent… mais encadré","auteur":"Texte écrit pour l’exercice","blocs":["Dimanche, les joueurs se plaquent de toutes leurs forces. Pourtant, personne ne se bat vraiment : un arbitre siffle chaque faute, et les règles interdisent les coups dangereux.","Pour le sociologue Norbert Elias, c’est un exemple du « processus de civilisation » : au fil des siècles, la violence a été peu à peu contrôlée, et le sport permet de s’affronter sans se blesser gravement."]}],"questions":[{"enonce":"Touche les deux mots qui montrent que la violence est **encadrée**.","aide":"Qui fait respecter le jeu, et qu’est-ce qui dit ce qui est permis ?","type":"zone","document":"rugby","multiple":true},{"enonce":"Quel sociologue a décrit ce « processus de civilisation » ?","aide":"Son nom est dans le second paragraphe.","type":"texte","placeholder":"Son nom"},{"enonce":"Que veut dire « le sport canalise la violence » ?","aide":"Pense à ce que font l’arbitre et les règles dans le texte.","type":"choix","options":[{"id":"a","texte":"Il interdit aux joueurs de se toucher"},{"id":"b","texte":"Il donne à la violence un cadre de règles où l’on s’affronte sans se blesser gravement"},{"id":"c","texte":"Il rend la violence plus forte"},{"id":"d","texte":"Il supprime toute forme de contact entre joueurs"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m22"]},"explication":"L’**arbitre** et les **règles** encadrent la violence : on s’affronte, mais dans des limites."},{"cle":{"type":"texte","acceptes":["elias","norbert elias"]},"affichage":"Elias","explication":"C’est **Norbert Elias** : pour lui, le sport canalise la violence."},{"cle":{"type":"choix","ids":["b"]},"explication":"Canaliser, c’est **guider** : le sport ne fait pas disparaître l’énergie violente, il l’enferme dans un jeu réglementé."}]$ex$::jsonb),
  ('3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Qui joue à quoi ?","competence":"lire-tableau","situation":"Un lycée imaginaire a interrogé les licenciés de quatre sports sur la profession de leurs parents. Les résultats donnent envie de relire l’analyse de Pierre Bourdieu (1978).","documents":[{"id":"enquete","type":"tableau","titre":"Licenciés selon la profession des parents","source":"Enquête imaginée pour l’exercice.","colonnes":["Sport","Parents cadres (%)","Parents ouvriers (%)"],"lignes":[["Golf",62,8],["Tennis",48,14],["Football",18,36],["Boxe",9,44]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case du sport où la part de licenciés **de parents ouvriers** est la plus forte.","aide":"Parcours la dernière colonne et repère le plus grand nombre.","type":"zone","document":"enquete","multiple":false},{"enonce":"Au tennis, de combien de points la part des enfants de cadres dépasse-t-elle celle des enfants d’ouvriers ?","aide":"Soustrais la part des parents ouvriers à celle des parents cadres, sur la ligne Tennis.","type":"nombre","unite":"points"},{"enonce":"Selon l’analyse de Bourdieu (1978), range ces sports : plutôt liés aux classes aisées, ou aux classes populaires ?","aide":"Le tableau t’aide pour quatre sports. Pour l’équitation, pense au coût et aux lieux de pratique.","type":"categories","categories":[{"id":"c0","texte":"Plutôt classes aisées"},{"id":"c1","texte":"Plutôt classes populaires"}],"items":[{"id":"i0","texte":"Football"},{"id":"i1","texte":"Équitation"},{"id":"i2","texte":"Boxe"},{"id":"i3","texte":"Tennis"},{"id":"i4","texte":"Golf"}]},{"enonce":"Que peut-on conclure de ce tableau, avec prudence ?","aide":"Une tendance n’est pas une loi. Écarte les réponses qui disent « toujours » ou « jamais ».","type":"choix","options":[{"id":"a","texte":"Le milieu social n’a aucun lien avec le sport"},{"id":"b","texte":"Le choix d’un sport est lié au milieu social (coût, lieux, codes), mais ce n’est pas une règle absolue"},{"id":"c","texte":"On ne peut pratiquer que le sport de son milieu"},{"id":"d","texte":"Les cadres sont meilleurs au tennis que les ouvriers"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c2"]},"explication":"C’est la **boxe** : 44 % de licenciés ont des parents ouvriers."},{"cle":{"type":"nombre","valeur":34,"tolerance":0},"affichage":"34 points","explication":"48 − 14 = **34 points** d’écart : le tennis recrute nettement plus dans les milieux aisés."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Golf, tennis, équitation sont plutôt liés aux classes aisées ; boxe et football aux classes populaires. C’est une grille de lecture **ancienne et discutée**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le tableau montre une **tendance**, pas un destin : les pratiques ont évolué depuis 1978, mais la grille de Bourdieu aide à comprendre."}]$ex$::jsonb),
  ('3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, 3, 3, 5, 50, 5,
   $ex${"titre":"Le stade, miroir de la société","competence":"argumenter","situation":"Anaïs et Karim débattent. Karim pense que le sport est « un monde à part ». Anaïs lui répond avec des repères de l’histoire du sport.","documents":[{"id":"frise-stade","type":"frise","titre":"Quelques dates du sport et de la société","source":"Repères historiques.","debut":1945,"fin":2020,"pas":5,"evenements":[{"id":"z1","date":1948,"nom":"Stoke Mandeville"},{"id":"z2","date":1960,"nom":"Jeux de Rome"},{"id":"z3","date":1985,"nom":"Heysel"},{"id":"z4","date":1989,"nom":"Hillsborough"},{"id":"z5","date":1998,"nom":"Première étoile"},{"id":"z6","date":2018,"nom":"Deuxième étoile"}]},{"id":"debat","type":"dialogue","modele":"sms","titre":"Le débat","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Karim","emoji":"👦","cote":"gauche"},{"nom":"Anaïs","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Karim","texte":"Pour moi, le sport est un monde à part. Ça n’a rien à voir avec la société."},{"qui":"Anaïs","texte":"Alors pourquoi chante-t-on l’hymne avant chaque match ? Pourquoi les Jeux paralympiques existent ? Pourquoi Heysel a changé la sécurité des stades ?"}]}],"questions":[{"enonce":"Touche les trois **exemples** qu’Anaïs oppose à Karim.","aide":"Cherche les mots qui renvoient à un symbole, à une institution, à un drame.","type":"zone","document":"debat","multiple":true},{"enonce":"Touche l’événement, né en **1948** pour des blessés de guerre, à l’origine des Jeux paralympiques.","aide":"Place-toi sur 1948 : c’est le premier événement de la frise.","type":"zone","document":"frise-stade","multiple":false},{"enonce":"Combien d’années séparent le drame du Heysel de celui de Hillsborough ?","aide":"Lis les dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque repère de la frise à l’idée qu’il illustre.","aide":"Pense à ce que chacun montre de la société : qui joue, qui se bat, qui se rassemble.","type":"association","gauche":[{"id":"g0","texte":"Stoke Mandeville (1948)"},{"id":"g1","texte":"Heysel (1985)"},{"id":"g2","texte":"Les deux étoiles (1998, 2018)"}],"droite":[{"id":"d0","texte":"La violence de supporters et la sécurité"},{"id":"d1","texte":"L’identité et l’appartenance à une nation"},{"id":"d2","texte":"L’inclusion par le sport"}]},{"enonce":"Quelle idée du cours Anaïs défend-elle ?","aide":"Reprends la dernière réplique d’Anaïs : que montrent ses trois exemples ?","type":"choix","options":[{"id":"a","texte":"Le sport est uniquement un jeu sans conséquence"},{"id":"b","texte":"Le sport doit être interdit aux supporters"},{"id":"c","texte":"Le sport n’a qu’une dimension économique"},{"id":"d","texte":"Le sport est un miroir de la société, avec ses fiertés, ses inégalités et ses tensions"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22","m29","m32"]},"explication":"L’**hymne**, les Jeux **paralympiques** et **Heysel** : identité, inclusion, violence des supporters. Trois façons dont la société entre dans le stade."},{"cle":{"type":"zone","ids":["z1"]},"explication":"La compétition de **Stoke Mandeville** (1948) est à l’origine du mouvement paralympique ; la première édition officielle a lieu à Rome en 1960."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 ans","explication":"1989 − 1985 = **4 ans**. Ces deux drames ont conduit à renforcer la sécurité dans les stades."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le sport est un **miroir** : il montre l’inclusion, les tensions et les fiertés collectives. Karim a tort de le croire coupé de la société."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le sport est une **institution**, une **économie** et un **discours** : il reflète la société qui le pratique."}]$ex$::jsonb),
  ('0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Paris 2024 en bref","competence":"lire-tableau","situation":"Pour son exposé sur l’olympisme, Yanis a recopié les chiffres clés de Paris 2024 et les trois valeurs de la Charte olympique.","documents":[{"id":"chiffres","type":"tableau","titre":"Paris 2024 en chiffres","source":"Chiffres arrondis.","colonnes":["Donnée","Valeur"],"lignes":[["Sites existants ou temporaires","environ 95 %"],["Athlètes","environ 10 500"],["Places pour les femmes et pour les hommes","autant des unes que des autres (parité)"],["Billetterie paralympique","un record de ventes"]],"enteteLignes":true},{"id":"valeurs","type":"fiche","modele":"affiche","entete":"LES TROIS VALEURS OLYMPIQUES","emoji":"🏅","lignes":[{"texte":"Excellence : donner le meilleur de soi, pas seulement gagner","id":"z1"},{"texte":"Amitié : rapprocher des peuples par le sport","id":"z2"},{"texte":"Respect : respecter les règles, les adversaires, soi-même","id":"z3"}],"pied":"D’après la Charte olympique","teinte":"jaune"}],"questions":[{"enonce":"Touche la case qui donne la part de **sites existants ou temporaires**.","aide":"Cherche la première ligne du tableau.","type":"zone","document":"chiffres","multiple":false},{"enonce":"Imagine des Jeux avec 20 sites dont 95 % existants ou temporaires. Combien de sites sont dans ce cas ?","aide":"Calcule 95 % de 20.","type":"nombre","unite":"sites"},{"enonce":"Relie chaque valeur olympique à sa définition.","aide":"Relis la fiche des trois valeurs.","type":"association","gauche":[{"id":"g0","texte":"Excellence"},{"id":"g1","texte":"Amitié"},{"id":"g2","texte":"Respect"}],"droite":[{"id":"d0","texte":"Rapprocher des peuples par le sport"},{"id":"d1","texte":"Respecter les règles, les adversaires, soi-même"},{"id":"d2","texte":"Donner le meilleur de soi, pas seulement gagner"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Environ **95 %** des sites de Paris 2024 étaient existants ou temporaires : c’est l’esprit de l’Agenda 2020."},{"cle":{"type":"nombre","valeur":19,"tolerance":0},"affichage":"19 sites","explication":"0,95 × 20 = **19 sites** : un seul site est à construire."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Excellence, amitié et respect forment le cœur de la **Charte olympique**."}]$ex$::jsonb),
  ('0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Un an après les Jeux","competence":"analyser-texte","situation":"Un an après la fin des Jeux de Paris, un journal de quartier imaginé fait le point. Lis l’article en gardant un œil sur ce qui reste et sur ce qui fâche.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Que reste-t-il de la fête ?","auteur":"Article imaginé pour l’exercice","blocs":["Le CIO avait promis, avec l’Agenda 2020, des Jeux moins chers qui réutilisent des sites existants. À Paris, environ 95 % des sites étaient existants ou temporaires.","Le village olympique, à Saint-Denis, Saint-Ouen et L’Île-Saint-Denis, est devenu un quartier de logements. Le centre aquatique de Saint-Denis accueille habitants et clubs. Depuis 2025, on peut de nouveau se baigner dans la Seine.","Mais des associations rappellent le coût de l’événement, la lourdeur des mesures de sécurité et les délogements de personnes en précarité avant l’été 2024."]}],"questions":[{"enonce":"Touche les trois mots qui désignent un **héritage concret** des Jeux.","aide":"Cherche ce qui reste utile aux habitants après la fête : un lieu de vie, un équipement, un loisir.","type":"zone","document":"article","multiple":true},{"enonce":"Touche les trois mots qui désignent des **critiques** adressées aux Jeux.","aide":"Dans le dernier paragraphe, repère ce que reprochent les associations.","type":"zone","document":"article","multiple":true},{"enonce":"Range ces éléments : héritage ou controverse ?","aide":"Un héritage profite aux habitants après les Jeux ; une controverse est une critique ou un problème.","type":"categories","categories":[{"id":"c0","texte":"Héritage"},{"id":"c1","texte":"Controverse"}],"items":[{"id":"i0","texte":"Mesures de sécurité très lourdes"},{"id":"i1","texte":"Délogements avant les Jeux"},{"id":"i2","texte":"Seine rendue à la baignade"},{"id":"i3","texte":"Coût de l’événement"},{"id":"i4","texte":"Logements au village olympique"},{"id":"i5","texte":"Piscines rénovées"}]},{"enonce":"Quel principe de l’Agenda 2020 l’article illustre-t-il avec le chiffre de 95 % ?","aide":"Relis le premier paragraphe : qu’a promis le CIO ?","type":"choix","options":[{"id":"a","texte":"Une trêve olympique sur tous les conflits"},{"id":"b","texte":"Des Jeux entièrement construits à neuf"},{"id":"c","texte":"La parité entre athlètes"},{"id":"d","texte":"Des Jeux moins chers qui réutilisent des sites existants"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m41","m44","m58"]},"explication":"Des **logements**, un centre **aquatique**, la **baignade** dans la Seine : trois héritages concrets, pour les habitants."},{"cle":{"type":"zone","ids":["m67","m76","m79"]},"explication":"Le **coût**, la **sécurité** et les **délogements** : les controverses. Un bon bilan cite les bénéfices ET les critiques."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Seine, piscines, logements : l’**héritage**. Coût, délogements, sécurité : les **controverses**."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’**Agenda 2020** demande des Jeux moins chers qui réutilisent des sites. Un bon héritage se prépare avant les Jeux : on ne construit que ce dont on se servira ensuite."}]$ex$::jsonb),
  ('0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, 3, 3, 5, 50, 5,
   $ex${"titre":"Deux villes, un seul héritage","competence":"argumenter","situation":"Deux villes imaginées, A et B, se portent candidates pour des Jeux d’été. Le comité de sélection compare leurs dossiers avec les principes de l’Agenda 2020 du CIO.","documents":[{"id":"dossiers","type":"tableau","titre":"Les deux dossiers de candidature","source":"Villes et chiffres imaginés pour l’exercice.","colonnes":["Critère","Ville A","Ville B"],"lignes":[["Sites à construire",12,2],["Sites existants ou temporaires",3,38],["Quartier de logements après les Jeux","non prévu","prévu"],["Piscines ouvertes aux habitants ensuite","aucune","quatre"]],"enteteLignes":true},{"id":"agenda","type":"fiche","modele":"affiche","entete":"AGENDA 2020 DU CIO","emoji":"📜","lignes":[{"texte":"Des Jeux moins chers","id":"z1"},{"texte":"Réutiliser les sites existants","id":"z2"},{"texte":"Ne construire que ce dont on se servira ensuite","id":"z3"}],"pied":"Principes résumés pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Touche, dans le dossier, la case qui **contredit le plus** l’Agenda 2020 pour la ville A.","aide":"L’Agenda 2020 dit de ne pas tout construire. Quelle case montre le contraire ?","type":"zone","document":"dossiers","multiple":false},{"enonce":"Quelle est la part de sites **existants ou temporaires** dans le dossier de la ville B, sur l’ensemble de ses sites ? Réponds en pourcentage.","aide":"Total de sites de B : 2 + 38. Puis divise 38 par ce total.","type":"nombre","unite":"%"},{"enonce":"Quelle est la part de sites existants ou temporaires dans le dossier de la ville A ?","aide":"Total de sites de A : 12 + 3. Puis divise 3 par ce total.","type":"nombre","unite":"%"},{"enonce":"Quel dossier est le plus proche de l’esprit de l’Agenda 2020 ?","aide":"Confronte chaque ligne de la fiche de l’Agenda aux deux colonnes du tableau.","type":"choix","options":[{"id":"a","texte":"La ville A : plus de chantiers veut dire plus d’emplois"},{"id":"b","texte":"La ville B : peu de constructions, un quartier et des piscines qui serviront ensuite"},{"id":"c","texte":"Aucun : l’Agenda 2020 ne parle pas des sites"},{"id":"d","texte":"Les deux, car elles parlent d’héritage"}],"multiple":false},{"enonce":"Même si B est un meilleur dossier, quelle question un esprit critique doit-il encore poser ?","aide":"Pense aux trois critiques faites à Paris 2024 : coût, sécurité, délogements.","type":"choix","options":[{"id":"a","texte":"Quel est le sport le plus regardé à la télévision ?"},{"id":"b","texte":"Quelle ville a le plus beau logo ?"},{"id":"c","texte":"Aucune : un bon dossier n’appelle pas de critique"},{"id":"d","texte":"Combien cela coûtera-t-il, qui paiera, et que deviennent les habitants concernés par les travaux ?"}],"multiple":false}]}$ex$::jsonb,
