   $ex$[{"cle":{"type":"zone","ids":["m47","m51","m53"]},"explication":"L’EPPCS associe **sciences du sport**, **histoire** et **sociologie**, plus un projet collectif."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c1"}},"explication":"L’**option** : pratique, réflexion, contrôle continu, trois heures. L’**EPPCS** : sciences, histoire, sociologie, projet, écrit."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’EPPCS comporte de l’**écrit**. Pour qui aime surtout pratiquer, l’option approfondit la pratique, avec de la réflexion."}]$ex$::jsonb),
  ('f16056b9-301c-5bcd-8db0-72e8c31a1dbb'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Est-ce pour moi ?","competence":"argumenter","situation":"Trois jeunes sportifs ont des projets très différents. Leur conseiller doit leur indiquer la structure scolaire adaptée et dire si l’EPPCS peut les intéresser.","documents":[{"id":"structures","type":"tableau","titre":"Les structures autour du sport au lycée","source":"Tableau résumé pour l’exercice.","colonnes":["Structure","Ce qu’elle permet"],"lignes":[["Section sportive scolaire","s’entraîner davantage pendant les heures de classe"],["Pôle espoirs","accueille des jeunes à fort potentiel"],["Sport-études","scolarité adaptée aux entraînements"],["Aménagements de sportif de haut niveau","horaires et examens adaptés"]],"enteteLignes":true},{"id":"profils","type":"texte","genre":"consigne","titre":"Les trois profils","auteur":"Textes écrits pour l’exercice","blocs":["Lina joue au handball. Elle voudrait s’entraîner davantage, mais sur le temps de classe.","Maël, nageur, a été repéré pour son fort potentiel. Il vise aussi des études de STAPS et aime écrire autant que nager.","Yanis participe à des compétitions internationales. Ses dates tombent parfois pendant les examens."]}],"questions":[{"enonce":"Relie chaque jeune à la structure la plus adaptée.","aide":"Compare le besoin de chaque jeune avec la colonne « Ce qu’elle permet ».","type":"association","gauche":[{"id":"g0","texte":"Lina, plus d’entraînement sur le temps de classe"},{"id":"g1","texte":"Maël, repéré pour son fort potentiel"},{"id":"g2","texte":"Yanis, compétitions pendant les examens"}],"droite":[{"id":"d0","texte":"Aménagements de sportif de haut niveau"},{"id":"d1","texte":"Section sportive scolaire"},{"id":"d2","texte":"Pôle espoirs"}]},{"enonce":"Touche la structure qui organise **toute une scolarité** autour des entraînements.","aide":"Cherche la ligne qui parle d’une scolarité « adaptée ».","type":"zone","document":"structures","multiple":false},{"enonce":"Maël vise STAPS et aime écrire autant que nager. Que lui dire de la spécialité EPPCS ?","aide":"Qui s’intéresse à l’EPPCS selon le cours ? Croise avec le profil de Maël.","type":"choix","options":[{"id":"a","texte":"Elle remplace le sport par des cours de maths"},{"id":"b","texte":"Elle est faite pour ceux qui détestent écrire"},{"id":"c","texte":"Elle peut lui convenir : pratique, sciences, histoire, sociologie, et un écrit, avec STAPS pour horizon"},{"id":"d","texte":"Elle ne lui servira à rien, puisqu’elle ne mène à aucune étude"}],"multiple":false},{"enonce":"Quel piège doit connaître un élève avant de choisir l’EPPCS ?","aide":"Pense à ce qui change entre jouer au sport et l’étudier.","type":"choix","options":[{"id":"a","texte":"Elle est réservée aux sportifs de haut niveau"},{"id":"b","texte":"Elle ne compte jamais pour le bac"},{"id":"c","texte":"Ce n’est pas un cours de sport en plus : il y a de l’écrit et des notions à maîtriser"},{"id":"d","texte":"Elle se passe uniquement en salle de classe, sans pratique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Section sportive pour **s’entraîner plus en classe**, pôle espoirs pour le **fort potentiel**, aménagements pour **concilier examens et compétitions**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le **sport-études** organise une scolarité adaptée aux entraînements."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’EPPCS s’adresse à celles et ceux qui aiment **à la fois pratiquer et réfléchir**, et qui visent souvent STAPS, kinésithérapie, éducation ou management du sport."},{"cle":{"type":"choix","ids":["c"]},"explication":"Choisir l’EPPCS, c’est accepter de **travailler comme dans une matière théorique** : consulte le programme officiel et demande conseil à tes professeurs d’EPS."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier Tle : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;


-- =============================================================================
-- 575 — LE CATALOGUE DES CONTRÔLES BLANCS : Tle (sport)
--
-- 30 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 575 --niveau Tle --matieres sport
--
--   sport.culture                30 sujets · 10 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 1, 'redaction', $exo${"titre":"Les cycles d’une saison","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Nomme les trois échelles de temps d’une planification et donne la durée de chacune.\n2. Cite les **quatre périodes** de la saison décrites par Matveïev et dis ce que l’on fait pendant la préparation générale.\n3. Qu’est-ce que l’**affûtage** ? Précise sa durée et ce que l’on change (ou non).","bareme":[{"critere":"Macrocycle (saison), mésocycle (3 à 6 semaines), microcycle (semaine) nommés avec leur durée","points":6},{"critere":"Quatre périodes citées (générale, spécifique, compétition, transition) et préparation générale : beaucoup de volume, on bâtit le moteur","points":7},{"critere":"Affûtage défini : 1 à 3 semaines, volume réduit de 40 à 60 %, intensité conservée","points":7}],"dureeMin":7,"corrige":"1. Le **macrocycle** est la saison entière ; le **mésocycle** dure de **3 à 6 semaines** et sert à développer une qualité (endurance, force, vitesse) ; le **microcycle** est la **semaine**, où l’on répartit séances dures et légères.\n\n2. Les quatre périodes, décrites par le Soviétique **Lev Matveïev** dans les années 1960, sont la **préparation générale**, la **préparation spécifique**, la **compétition** et la **transition**. Pendant la préparation générale, on fait **beaucoup de volume** avec des exercices variés : on **bâtit le moteur**.\n\n3. L’**affûtage** est la phase qui précède l’objectif : il dure de **1 à 3 semaines**. On **réduit le volume de 40 à 60 %** mais on **garde l’intensité**, pour que le corps efface la fatigue sans perdre ses acquis ni la fraîcheur des gestes rapides."}$exo$::jsonb),
  ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 2, 'redaction', $exo${"titre":"La saison de Chloé","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Chloé, nageuse de 17 ans, vise les **championnats de France en avril**. Elle nage 20 heures par semaine et a prévu l’enchaînement suivant : *septembre à décembre, quatre semaines sur quatre au maximum ; en mars, elle ne change rien ; elle veut aussi réussir une compétition en janvier, une autre en mars et les championnats en avril, tous à son « pic de forme ». Ses épreuves de bac blanc tombent en plein mois de mars.*\n\n1. Relève **trois erreurs** dans son plan et corrige chacune.\n2. Calcule le volume hebdomadaire qu’elle pourrait viser pendant l’affûtage et explique ce qu’elle doit garder.\n3. Où placer sa semaine de **décharge** par rapport aux épreuves de bac blanc ? Justifie.","bareme":[{"critere":"Trois erreurs corrigées : pas de décharge, pas d’affûtage, trois pics de forme visés alors qu’un pic ne tient que quelques semaines","points":9},{"critere":"Volume d’affûtage calculé (de 8 à 12 heures, soit 20 h réduites de 40 à 60 %) et intensité gardée","points":6},{"critere":"Décharge placée au moment des examens, loin de la charge maximale, car les épreuves pèsent sur le sommeil et l’énergie","points":5}],"dureeMin":12,"corrige":"1. **Pas de décharge** : quatre semaines dures d’affilée empilent de la fatigue sans la transformer en progrès ; il faut environ **trois semaines dures pour une légère**, afin que la surcompensation se fasse. **Pas d’affûtage** : en mars elle devrait préparer son pic en réduisant la charge, et non « ne rien changer ». **Trois pics de forme** : un pic ne se tient que **quelques semaines**, viser trois objectifs majeurs, c’est souvent en rater deux ; elle doit choisir l’objectif principal (les championnats) et traiter les autres comme des étapes.\n\n2. Réduire 20 heures de **40 à 60 %** donne un volume d’environ **8 à 12 heures par semaine**. Elle doit **garder l’intensité** : sans elle, elle perdrait la vivacité de ses gestes rapides.\n\n3. Les épreuves de bac blanc pèsent sur le sommeil et l’énergie : sa **décharge** doit tomber à ce moment-là, et ses semaines les plus dures se placer loin des révisions intenses. Une bonne saison tient compte du **calendrier scolaire** autant que du calendrier sportif."}$exo$::jsonb),
  ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 3, 'redaction', $exo${"titre":"Peut-on être au sommet toute l’année ?","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un camarade affirme : « Pour devenir meilleur, il suffit de s’entraîner le plus possible, toute l’année, sans jamais lever le pied. Un vrai sportif doit être à son pic de forme de septembre à juin. »*\n\nRéponds à cette affirmation en un texte argumenté d’environ vingt lignes :\n- explique pourquoi elle est fausse en t’appuyant sur la **charge et la décharge**, l’**affûtage** et la durée d’un **pic de forme** ;\n- présente la **périodisation** de Matveïev, puis la **périodisation par blocs** d’Issurin ;\n- conclus en indiquant comment tu dessinerais ta propre saison, bac compris.","bareme":[{"critere":"Réfutation argumentée : on progresse pendant la récupération, la décharge fait la surcompensation, un pic ne tient que quelques semaines","points":7},{"critere":"Périodisation de Matveïev (quatre périodes) et périodisation par blocs (une qualité à la fois, Issurin) expliquées avec précision","points":6},{"critere":"Conclusion : saison dessinée à rebours depuis la date clé, décharges et affûtage placés, calendrier du bac pris en compte","points":4},{"critere":"Qualité de la rédaction : plan clair, vocabulaire du cours, phrases construites","points":3}],"dureeMin":15,"corrige":"**Introduction.** L’affirmation de ce camarade est séduisante mais **fausse** : s’entraîner plus n’est pas s’entraîner mieux, et personne ne peut rester au sommet dix mois.\n\n**Pourquoi c’est faux.** Le corps ne progresse pas pendant l’effort mais **pendant la récupération** : l’effort lance le signal, le repos fabrique le progrès (c’est la **surcompensation**). D’où la règle de **trois semaines dures pour une semaine légère** : sauter la **décharge**, c’est empiler de la fatigue sans la transformer en progrès, et risquer le surentraînement. Ensuite, un **pic de forme ne se tient que quelques semaines** : pour y arriver frais le jour J, on pratique l’**affûtage**, de **1 à 3 semaines**, en réduisant le volume de **40 à 60 %** tout en **gardant l’intensité**. Être au sommet de septembre à juin est donc impossible, et viser trop d’objectifs majeurs revient souvent à en rater plusieurs.\n\n**Deux manières de planifier.** Dans les années 1960, **Lev Matveïev** a décrit la **périodisation** : un macrocycle (la saison) découpé en **préparation générale** (beaucoup de volume), **préparation spécifique** (le travail se rapproche du sport, l’intensité monte), **compétition** et **transition** (repos actif). Plus récemment, **Vladimir Issurin** a proposé la **périodisation par blocs** : on concentre l’entraînement sur **une seule qualité à la fois** pendant quelques semaines (mésocycles de 3 à 6 semaines), puis on enchaîne.\n\n**Conclusion.** Pour ma saison, je partirais de ma **date clé**, je remonterais le temps en comptant mes semaines, je poserais d’abord mes décharges et ma transition, puis j’ajusterais : mes épreuves de **bac** ne doivent pas tomber en pleine charge, et je prévoirais une décharge au moment des examens. Un bon entraînement est un plan qui alterne l’effort et le repos."}$exo$::jsonb),
  ('c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, 1, 'redaction', $exo${"titre":"Les repères du cœur","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Définis la **FC de repos**, la **FC max** et la **FC de réserve**.\n2. Écris la **formule de Karvonen** et explique à quoi elle sert.\n3. Que mesure le **test de Cooper** ? Et que signifie **VMA** ?","bareme":[{"critere":"FC de repos, FC max et FC de réserve (FC max − FC repos) correctement définies","points":7},{"critere":"Formule de Karvonen exacte (FC repos + % × (FC max − FC repos)) et son usage : viser une intensité","points":7},{"critere":"Cooper : distance parcourue en 12 minutes (endurance) ; VMA : vitesse maximale aérobie, référence pour régler ses allures","points":6}],"dureeMin":7,"corrige":"1. La **FC de repos** est le nombre de battements par minute au calme, au réveil : elle baisse avec l’entraînement. La **FC max** est le maximum que le cœur peut atteindre à l’effort. La **FC de réserve** est la différence **FC max − FC de repos** : la marge dont on dispose.\n\n2. **FC cible = FC repos + % × (FC max − FC repos)**. Cette formule de **Karvonen** sert à calculer la fréquence cardiaque à viser pour travailler à une intensité choisie (par exemple 70 %).\n\n3. Le **test de Cooper** mesure la **distance parcourue en 12 minutes**, reflet de l’**endurance**. La **VMA** est la **vitesse maximale aérobie** : la vitesse à laquelle l’organisme consomme le plus d’oxygène, référence pour régler ses allures de course."}$exo$::jsonb),
  ('c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, 2, 'redaction', $exo${"titre":"Une semaine de carnet","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Voici le carnet d’Adam, 17 ans, coureur. Sa **FC de repos est 55** et sa **FC max 195**.\n\n| Jour | Séance | Durée | RPE |\n| Lundi | footing léger | 50 min | 3 |\n| Mardi | fractionné | 60 min | 8 |\n| Jeudi | footing | 40 min | 4 |\n| Samedi | sortie longue | 90 min | 6 |\n\n1. Calcule la **charge de chaque séance** (méthode de Foster), puis la charge de la semaine.\n2. Quelle FC cible doit-il viser à **75 %** de sa réserve ? Détaille le calcul.\n3. La semaine précédente, la charge totale était de **700**. Calcule l’évolution et dis ce que le ratio aigu/chronique doit t’inciter à faire.","bareme":[{"critere":"Charges calculées par RPE × durée (150, 480, 160, 540) et total de la semaine (1 330)","points":7},{"critere":"FC cible à 75 % : 55 + 0,75 × (195 − 55) = 160, calcul détaillé","points":6},{"critere":"Hausse de 630 (soit 90 %) repérée ; conclusion : montée trop brutale, risque de blessure, il faut alléger et surveiller","points":7}],"dureeMin":12,"corrige":"1. **Charge = RPE × durée** : lundi 3 × 50 = **150** ; mardi 8 × 60 = **480** ; jeudi 4 × 40 = **160** ; samedi 6 × 90 = **540**. Total de la semaine : 150 + 480 + 160 + 540 = **1 330** unités.\n\n2. **FC de réserve** = 195 − 55 = 140. **FC cible = 55 + 0,75 × 140 = 55 + 105 = 160** battements par minute.\n\n3. 1 330 contre 700 : la charge a augmenté de **630**, soit environ **+ 90 %**, presque le double. En comparant la semaine en cours aux semaines précédentes (le **ratio aigu/chronique**), on repère une hausse trop brutale, qui **expose à la blessure**. Adam doit alléger la semaine suivante et surveiller sa FC de repos, son sommeil et son RPE. Mesurer ne suffit pas : il faut **interpréter** et décider."}$exo$::jsonb),
  ('c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, 3, 'redaction', $exo${"titre":"Mesurer n’est pas interpréter","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un joueur déclare : « Avec ma montre GPS, qui donne ma FC, ma distance et mon allure, je n’ai pas besoin de carnet ni de me fier à mes sensations. Les chiffres suffisent. »*\n\nRédige une réponse argumentée d’environ vingt lignes :\n- explique la différence entre **mesurer** et **interpréter**, avec un exemple chiffré ;\n- présente au moins **deux outils** (tests de terrain, RPE de Borg, variabilité cardiaque) et ce que chacun apporte ;\n- montre pourquoi le **carnet d’entraînement** reste indispensable, et fais le lien avec l’**AFL2** du bac ;\n- conclus sur les limites des capteurs.","bareme":[{"critere":"Distinction mesurer / interpréter claire, illustrée par un exemple (par exemple 168 pulsations qui ne disent rien sans FC max et objectif)","points":6},{"critere":"Au moins deux outils bien présentés : tests de terrain, RPE et charge de séance, variabilité cardiaque au réveil","points":6},{"critere":"Rôle du carnet (séance, durée, RPE, sommeil, humeur, ajustement) et lien avec l’AFL2 : s’entraîner, analyser, ajuster","points":5},{"critere":"Limites des capteurs et qualité de la rédaction","points":3}],"dureeMin":15,"corrige":"**Introduction.** Ce joueur confond **mesurer** et **interpréter**. Les outils modernes relèvent des chiffres ; seul un raisonnement les transforme en décisions.\n\n**Mesurer, ce n’est pas interpréter.** Une montre affiche 168 pulsations par minute. Bien ou mal ? Le chiffre seul ne dit rien : tout dépend de la **FC max**, de la **FC de repos**, du niveau de forme et de l’objectif de la séance. Avec la formule de Karvonen (FC repos + % × FC de réserve), on situe cette valeur dans une **zone d’intensité** de 1 à 5 : c’est l’interprétation qui donne du sens.\n\n**Des outils complémentaires.** Les **tests de terrain** (navette de Léger, VAMEVAL, Léger-Boucher, Cooper, 30-15 IFT) donnent une idée de la forme et de la **VMA**, qui sert à régler les allures. L’**échelle de Borg (RPE, de 1 à 10)** mesure le ressenti, et la **charge de séance = RPE × durée** (Foster), comparée à celle des semaines précédentes (**ratio aigu/chronique**), repère les hausses trop brutales qui exposent à la blessure. La **variabilité cardiaque** au réveil renseigne sur la fatigue du système nerveux.\n\n**Le carnet, outil gratuit et puissant.** On y note la date, la séance, la durée, le RPE, le sommeil et l’humeur, et surtout **ce qu’on change la prochaine fois**. C’est ce que l’**AFL2** du bac d’EPS évalue : **s’entraîner, analyser et ajuster**. Une semaine de carnet commentée vaut mieux que dix pages de chiffres sans réflexion.\n\n**Conclusion.** Les capteurs se trompent parfois et ne remplacent ni les sensations, ni le bon sens. La montre mesure, le carnet et le sportif interprètent."}$exo$::jsonb),
  ('58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, 1, 'redaction', $exo${"titre":"Stress et activation","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Quelles hormones le corps libère-t-il face à un enjeu, et quels effets observe-t-on ?\n2. Que dit la loi de **Yerkes-Dodson** ? Nomme la forme de la courbe.\n3. Décris la **cohérence cardiaque** (nombre de respirations par minute et durée).","bareme":[{"critere":"Adrénaline et cortisol nommés, avec des effets (cœur plus rapide, respiration, muscles tendus)","points":6},{"critere":"Yerkes-Dodson : la performance monte avec l’activation puis baisse ; courbe en U inversé ; niveau optimal","points":7},{"critere":"Cohérence cardiaque : environ 6 respirations par minute pendant 5 minutes (5 secondes d’inspiration, 5 d’expiration)","points":7}],"dureeMin":7,"corrige":"1. Face à un enjeu, le corps libère de l’**adrénaline** et du **cortisol** : le cœur accélère, la respiration s’emballe, les muscles se tendent. C’est une réponse normale, faite pour mobiliser.\n\n2. D’après la loi de **Yerkes-Dodson**, la performance **monte avec l’activation, puis redescend quand elle est excessive** : c’est une **courbe en U inversé**. Il existe un **niveau d’activation optimal** (concentration, énergie, précision) ; trop bas, on est mou ; trop haut, on se crispe et on fait des erreurs.\n\n3. La **cohérence cardiaque** consiste à respirer environ **6 fois par minute**, pendant **5 minutes** (inspirer 5 secondes, expirer 5 secondes). Elle apaise le rythme du cœur avant l’effort."}$exo$::jsonb),
  ('58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, 2, 'redaction', $exo${"titre":"Avant le Grand oral","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Inès doit passer son **Grand oral** dans une semaine. Elle raconte : *« Dès que j’y pense, mon cœur s’emballe. Je me dis que je vais forcément rater et que mon objectif est d’avoir 20/20. La veille, je répète mon texte mot à mot dans ma tête, et au moment de parler je m’entends surveiller chaque mot : je bégaie. »*\n\n1. Explique ce qui se passe dans son corps et dans sa tête (hormones, **courbe en U inversé**). Est-ce anormal ?\n2. Repère le **dialogue interne** et l’**objectif** problématiques, et propose une version corrigée de chacun (objectif de **processus**).\n3. Construis-lui une **routine** d’avant-prise de parole en utilisant au moins trois outils du cours.","bareme":[{"critere":"Stress expliqué (adrénaline, cortisol) comme réponse normale ; Inès est probablement trop activée, sur la partie droite de la courbe","points":6},{"critere":"Dialogue interne négatif et objectif de résultat identifiés ; reformulations positives et centrées sur le processus","points":7},{"critere":"Routine cohérente avec au moins trois outils (cohérence cardiaque, imagerie mentale, routine, consigne simple, attention étroite) et mention du choke","points":7}],"dureeMin":12,"corrige":"1. Son cœur qui s’emballe vient de l’**adrénaline** et du **cortisol** : c’est une réponse **normale**, faite pour mobiliser. Mais elle semble **trop activée** : sur la **courbe de Yerkes-Dodson** (en U inversé), au-delà de l’optimum la tension et les erreurs augmentent.\n\n2. Son **dialogue interne** (« je vais forcément rater ») installe l’échec ; elle devrait se dire : « **Une action à la fois**, je suis prête ». Son objectif de **résultat** (20/20) dépend du jury ; un objectif de **processus** dépend d’elle : « parler lentement, regarder le jury, respirer entre deux idées ». Un objectif **SMART** est précis et défini dans le temps.\n\n3. Routine possible : **cohérence cardiaque** (6 respirations par minute pendant 5 minutes), **imagerie mentale** (se voir réussir du début à la fin, comme Michael Phelps visualisait ses courses), puis une **routine d’avant-performance** fixe (mêmes gestes, comme Nadal avant un service) et une **consigne simple** pour garder l’attention sur son message. Surveiller chaque mot, c’est le **choke** : se concentrer sur le sens, pas sur le geste de parler."}$exo$::jsonb),
  ('58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, 3, 'redaction', $exo${"titre":"La santé mentale, partie de la performance","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un entraîneur déclare : « Un champion ne doit jamais douter ni s’arrêter. Le mental, c’est de la force de caractère : quand Simone Biles s’est retirée de plusieurs finales à Tokyo en 2021, elle a montré de la faiblesse. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- réponds à l’entraîneur en t’appuyant sur le stress, la courbe de **Yerkes-Dodson** et le **choke** ;\n- explique en quoi le mental **s’entraîne** (respiration, routine, imagerie, objectifs, dialogue interne) en donnant au moins trois exemples ;\n- discute la place de la **santé mentale** dans la performance ;\n- conclus en montrant comment ces outils servent aussi au **Grand oral**.","bareme":[{"critere":"Réfutation argumentée : le stress est normal, l’activation optimale est intermédiaire, le choke vient de la surveillance du geste","points":6},{"critere":"Au moins trois outils expliqués avec exemples (Nadal, Phelps, cohérence cardiaque, objectifs de processus, dialogue interne)","points":6},{"critere":"Santé mentale discutée : Biles, Tokyo 2021, débat sur le bien-être, demander de l’aide est une force","points":5},{"critere":"Conclusion sur le Grand oral et qualité de la rédaction","points":3}],"dureeMin":15,"corrige":"**Introduction.** L’entraîneur fait du mental un simple trait de caractère. Le cours dit l’inverse : le mental est une **préparation** qui **s’apprend**, comme un geste technique.\n\n**Le stress est normal.** Face à un enjeu, **adrénaline** et **cortisol** mobilisent le corps. La loi de **Yerkes-Dodson** (courbe en U inversé) montre que la performance est maximale à un niveau d’activation **intermédiaire** : ni mou, ni crispé. Le problème n’est donc pas de douter ou d’être stressé, mais de l’être **trop**. Au-delà, on surveille son propre geste au lieu de lui faire confiance : c’est le **choke**, la contre-performance sous pression.\n\n**Le mental s’entraîne.** La **cohérence cardiaque** (6 respirations par minute, 5 minutes) apaise le rythme du cœur. La **routine** d’avant-performance ancre l’attention : Rafael Nadal répète les mêmes gestes avant chaque service. L’**imagerie mentale** consiste à se voir réussir en détail, comme Michael Phelps visualisait ses courses, imprévus compris. Les objectifs de **processus** (« garder le dos droit ») dépendent de soi, contrairement aux objectifs de **résultat** (« gagner ») ; le **dialogue interne** se choisit (« une action à la fois »).\n\n**La santé mentale compte.** En 2021, aux Jeux de **Tokyo**, **Simone Biles** s’est retirée de plusieurs finales pour protéger sa santé mentale. Plutôt qu’une faiblesse, ce geste a ouvert un large débat sur le **bien-être des athlètes** : continuer à tout prix, c’est risquer la blessure et la contre-performance. **Demander de l’aide est une force.**\n\n**Conclusion.** Ces outils servent bien au-delà du terrain : le **Grand oral** est une performance sous enjeu, où souffle, routine, imagerie et objectif de processus s’appliquent exactement de la même façon."}$exo$::jsonb),
  ('3e6141f6-e362-5765-a122-b8532787e93a'::uuid, 1, 'redaction', $exo${"titre":"Fatigue, surmenage, surentraînement","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Distingue la **fatigue normale**, le **surmenage** et le **surentraînement** par la durée de la fatigue.\n2. Cite **quatre signes d’alerte** du surentraînement.\n3. Quel est le levier de récupération le plus puissant ? Précise la durée recommandée à un athlète adolescent.","bareme":[{"critere":"Les trois états distingués : quelques heures à un jour, quelques jours, des semaines voire des mois","points":6},{"critere":"Quatre signes exacts cités (performance en baisse, FC de repos élevée, sommeil perturbé, humeur, infections, perte d’appétit)","points":7},{"critere":"Sommeil désigné comme premier levier, 9 heures ou plus pour un athlète adolescent","points":7}],"dureeMin":7,"corrige":"1. La **fatigue normale** dure de quelques heures à un jour et signale un travail utile. Le **surmenage** dure **quelques jours** et demande d’alléger. Le **surentraînement** dure **des semaines, voire des mois** : c’est un vrai déséquilibre, qui exige un arrêt ou une forte baisse de charge et un avis médical.\n\n2. Signes d’alerte : une **performance qui baisse malgré le travail**, une **FC de repos élevée** au réveil, un **sommeil perturbé**, de l’**irritabilité** ou de l’anxiété, des **infections à répétition**, une **perte d’appétit** (il suffit d’en citer quatre).\n\n3. Le **sommeil** est le levier le plus puissant : **9 heures ou plus** pour un athlète adolescent. Massage, compression et bain froid viennent loin derrière."}$exo$::jsonb),
  ('3e6141f6-e362-5765-a122-b8532787e93a'::uuid, 2, 'redaction', $exo${"titre":"Le journal de Léo","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Voici trois semaines du carnet de Léo, 17 ans, qui prépare un tournoi et ses épreuves de bac.\n\n| | Semaine 1 | Semaine 2 | Semaine 3 |\n| FC de repos au réveil | 55 | 60 | 65 |\n| Sommeil par nuit | 8 h | 7 h | 6 h |\n| RPE d’une séance habituelle | 6 | 7 | 9 |\n| Séances par semaine | 5 | 6 | 7 |\n\n*Il se dit qu’il n’en fait pas assez, et prévoit d’ajouter encore une séance.*\n\n1. Relève **quatre indices** du carnet qui évoquent un surentraînement.\n2. Identifie **deux causes** possibles dans la vie de Léo.\n3. Que lui conseilles-tu ? Donne **trois mesures** de récupération et dis ce que l’on risquerait en ajoutant une séance.","bareme":[{"critere":"Quatre indices relevés dans le tableau, chiffres à l’appui (FC de repos de 55 à 65, sommeil de 8 h à 6 h, RPE de 6 à 9 pour une même séance, séances en hausse)","points":7},{"critere":"Deux causes : charge qui monte trop vite sans décharge, manque de sommeil, stress scolaire du bac","points":5},{"critere":"Conseils : alléger ou décharger, dormir davantage, nutrition, récupération active, avis médical ; risque : enfoncer le déséquilibre","points":8}],"dureeMin":12,"corrige":"1. Indices : la **FC de repos monte** de 55 à 65 ; le **sommeil diminue** de 8 h à 6 h ; le **RPE** d’une séance habituelle passe de **6 à 9** (le même travail coûte plus cher) ; le nombre de séances **augmente chaque semaine**. Plusieurs signes ensemble : c’est le tableau d’un début de **surentraînement**.\n\n2. Causes : une **charge qui monte trop vite**, sans **semaine de décharge** ; un **manque de sommeil** ; le **stress scolaire** des examens, qui s’ajoute à la fatigue sportive.\n\n3. Léo doit **alléger fortement sa charge** (une décharge, voire un arrêt), **dormir davantage** (9 h et plus, en coupant les écrans une heure avant), soigner sa **nutrition** (glucides et protéines), faire de la **récupération active** (marche, vélo léger) et en **parler à un médecin ou à son entraîneur**. Ajouter une séance irait à l’inverse : on progresse **pendant la récupération**, et il enfoncerait le déséquilibre entre charge et repos."}$exo$::jsonb),
  ('3e6141f6-e362-5765-a122-b8532787e93a'::uuid, 3, 'redaction', $exo${"titre":"Récupérer, c’est s’entraîner","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un lycéen sportif affirme : « Moins je dors et plus je m’entraîne, plus je progresse. Les massages et les bains froids remplacent largement le sommeil. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- réponds à cette affirmation en expliquant où se fait réellement le progrès et ce qu’est la **surcompensation** ;\n- compare le **sommeil**, la **nutrition**, la **récupération active**, le **massage**, la **compression** et le **bain froid** ;\n- appuie-toi sur l’**étude de Stanford** ;\n- explique comment la **planification** et le **carnet** préviennent le surentraînement.","bareme":[{"critere":"Réfutation : le progrès se fait au repos, l’effort lance le signal ; surcompensation expliquée","points":5},{"critere":"Comparaison argumentée des leviers de récupération (sommeil premier, massage et compression modestes, bain froid ambivalent)","points":7},{"critere":"Étude de Stanford citée correctement (basketteurs, environ 10 h de sommeil, sprints et lancers francs améliorés) et rôle des écrans","points":4},{"critere":"Prévention par la planification et le carnet ; qualité de la rédaction","points":4}],"dureeMin":15,"corrige":"**Introduction.** Cette affirmation est l’inverse de ce que montrent la physiologie et l’entraînement : on ne progresse pas en s’épuisant, mais en **récupérant**.\n\n**Où se fait le progrès ?** L’effort lance un signal ; c’est la récupération qui fabrique le progrès par la **surcompensation** : le corps répare, puis dépasse son niveau de départ. Sans repos, la fatigue s’accumule et conduit au **surmenage**, puis au **surentraînement** (fatigue de plusieurs semaines, performance qui baisse malgré le travail, FC de repos élevée, infections à répétition).\n\n**Quels leviers de récupération ?** Le **sommeil** est le plus puissant : **9 h et plus** pour un athlète adolescent. L’**étude de Stanford** a fait dormir des basketteurs environ **10 heures par nuit** : leurs **sprints et leurs lancers francs** se sont améliorés. La **nutrition** (glucides, protéines) refait les stocks ; la **récupération active** (marche, vélo léger, étirements doux) aide à relancer. Le **massage** et la **compression** ont un effet **modeste**, surtout de confort. Le **bain froid** soulage, mais s’il est pris **systématiquement**, il peut **freiner la prise de muscle**. Aucun ne remplace le sommeil. Les **écrans** le soir retardent l’endormissement : poser le téléphone une heure avant aide.\n\n**Prévenir.** La **planification** (décharges prévues, charge qui monte progressivement) et le **carnet** (FC de repos, sommeil, RPE) permettent d’alléger **avant** de craquer. Le stress scolaire compte aussi.\n\n**Conclusion.** Dormir peu pour s’entraîner plus est une fausse bonne idée : le sommeil est un entraînement invisible."}$exo$::jsonb),
  ('475d747d-a507-5860-ad09-00a4423612c4'::uuid, 1, 'redaction', $exo${"titre":"Les repères de l’OMS","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Quelle activité recommande l’OMS aux **5-17 ans** et aux **adultes** ?\n2. Distingue **inactivité physique** et **sédentarité**.\n3. Qu’est-ce que le **sport sur ordonnance** ? Donne l’année de la loi et celle de son élargissement.","bareme":[{"critere":"Recommandations exactes : 60 minutes par jour de 5 à 17 ans, 150 à 300 minutes par semaine pour les adultes","points":7},{"critere":"Inactivité (ne pas atteindre les niveaux recommandés) distinguée de la sédentarité (temps assis ou allongé éveillé)","points":7},{"critere":"Sport sur ordonnance : activité physique adaptée prescrite par un médecin ; loi de 2016, en vigueur en 2017, élargi en 2022","points":6}],"dureeMin":7,"corrige":"1. L’OMS recommande **60 minutes par jour** d’activité modérée à soutenue de **5 à 17 ans**, et **150 à 300 minutes par semaine** d’activité modérée pour les **adultes**.\n\n2. L’**inactivité physique** est le fait de **ne pas atteindre les niveaux d’activité recommandés** ; la **sédentarité** est le **temps passé assis ou allongé en étant éveillé** (écran, classe, transports). On peut faire une heure de sport et rester sédentaire le reste de la journée : **les deux comptent**.\n\n3. Le **sport sur ordonnance** permet à un médecin de **prescrire de l’activité physique adaptée**, notamment aux personnes atteintes d’une maladie de longue durée. La **loi date de 2016**, elle est **en vigueur depuis 2017** et le dispositif a été **élargi en 2022**."}$exo$::jsonb),
  ('475d747d-a507-5860-ad09-00a4423612c4'::uuid, 2, 'redaction', $exo${"titre":"Une journée de Maxime","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Maxime, 16 ans, a une journée type : *7 h 30 de cours, 1 h 30 de transport assis, 3 h d’écrans le soir. Il fait 30 minutes de sport le mercredi et rien d’autre. Il dit : « Je suis actif, je fais du sport ! »* Il lit aussi cette statistique de l’ANSES (2020) : **deux tiers des 11-17 ans** présentent un risque sanitaire préoccupant.\n\n1. Compare son activité à la recommandation de l’OMS pour son âge : atteint-il la cible ? Calcule ce qu’il fait sur une semaine par rapport à ce qui est recommandé.\n2. Pourquoi peut-on dire qu’il est à la fois **inactif** et **sédentaire** ? Explique la différence.\n3. Propose **trois changements** réalistes et cite **trois bénéfices** de l’activité physique.","bareme":[{"critere":"Comparaison chiffrée : 30 min par semaine contre 60 min par jour, soit 420 min par semaine recommandées ; cible loin d’être atteinte","points":7},{"critere":"Inactif (activité sous la recommandation) et sédentaire (longs temps assis) : deux risques distincts qui se cumulent","points":6},{"critere":"Trois changements concrets (se lever à chaque pause, marcher, couper le téléphone plus tôt) et trois bénéfices (cœur, poids, diabète, santé mentale, sommeil)","points":7}],"dureeMin":12,"corrige":"1. L’OMS recommande **60 minutes par jour** à 16 ans, soit **420 minutes par semaine**. Maxime n’en fait que **30**, environ 7 % de la cible : il est **très loin** de la recommandation. Il fait partie du profil des deux tiers de jeunes de 11-17 ans en risque sanitaire préoccupant selon l’**ANSES (2020)**.\n\n2. Il est **inactif** parce qu’il n’atteint pas les niveaux d’activité recommandés. Il est **sédentaire** parce qu’il passe l’essentiel de la journée assis (cours, transport, écrans). Les deux sont des risques **distincts** qui se cumulent : trente minutes de sport ne compensent pas des heures assis.\n\n3. Changements : se **lever à chaque pause**, **marcher** pour une partie de ses trajets, **couper le téléphone plus tôt** le soir (et bouger davantage au quotidien). Bénéfices : **cœur** plus efficace et tension plus basse, moins de risque de **surpoids**, meilleur contrôle du sucre (**diabète**), moins d’anxiété (**santé mentale**), meilleur **sommeil**."}$exo$::jsonb),
  ('475d747d-a507-5860-ad09-00a4423612c4'::uuid, 3, 'redaction', $exo${"titre":"Le sport est-il une affaire de santé publique ?","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un internaute écrit : « Le sport est un loisir, pas une question de santé publique. Faire de l’activité, c’est un choix personnel, l’État n’a pas à s’en mêler. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- montre, avec des **chiffres** (OMS, ANSES), pourquoi le sport est un enjeu de santé publique ;\n- présente trois dispositifs publics (**sport sur ordonnance**, **Maisons Sport-Santé**, **30 minutes d’activité physique quotidienne** à l’école, **grande cause nationale** 2024) en précisant leurs dates ;\n- explique la différence entre **sédentarité** et **inactivité** et pourquoi elle compte pour l’action publique ;\n- conclus en nuançant : où s’arrête l’action de l’État et où commence celle de chacun ?","bareme":[{"critere":"Enjeu démontré par des chiffres : inactivité, premier facteur de risque de mortalité (OMS) ; deux tiers des 11-17 ans en risque (ANSES, 2020)","points":6},{"critere":"Trois dispositifs datés : loi de 2016 (élargie en 2022), Maisons Sport-Santé (2019), 30 minutes à l’école (2022), grande cause 2024","points":6},{"critere":"Sédentarité et inactivité distinguées ; conséquences pour l’action publique et pour chacun (bénéfices cœur, poids, diabète, santé mentale, sommeil)","points":4},{"critere":"Conclusion nuancée et qualité de la rédaction","points":4}],"dureeMin":15,"corrige":"**Introduction.** Présenter le sport comme un simple loisir ignore les chiffres : l’activité physique est un enjeu de **santé publique**.\n\n**Des chiffres qui alertent.** L’**OMS** range l’**inactivité physique** parmi les **premiers facteurs de risque de mortalité** dans le monde. Elle recommande **60 minutes par jour** de 5 à 17 ans et **150 à 300 minutes par semaine** pour les adultes. En France, selon l’**ANSES (2020)**, **deux tiers des 11-17 ans** présentent un risque sanitaire préoccupant (trop d’écrans, pas assez d’activité). Les bénéfices sont établis : cœur et tension, poids, **diabète**, **santé mentale** (moins d’anxiété), **sommeil**.\n\n**Des dispositifs publics.** La **loi de 2016**, en vigueur depuis **2017** et **élargie en 2022**, permet le **sport sur ordonnance** : un médecin prescrit de l’**activité physique adaptée** aux personnes atteintes d’une maladie de longue durée. Les **Maisons Sport-Santé** (à partir de **2019**) orientent, conseillent et suivent ceux qui reprennent. Depuis **2022**, l’école primaire propose **30 minutes d’activité physique quotidienne**, et l’activité physique a été **grande cause nationale en 2024**, année des Jeux de Paris.\n\n**Deux problèmes distincts.** L’**inactivité** est de ne pas atteindre les niveaux recommandés ; la **sédentarité** est le temps passé assis. On peut faire du sport et rester sédentaire : l’action publique doit donc agir sur le sport **et** sur les modes de vie (pauses actives, trajets, écrans).\n\n**Conclusion.** Le choix reste personnel, mais quand deux tiers des adolescents sont en risque, la collectivité est concernée : l’État facilite (ordonnance, école, Maisons Sport-Santé), et chacun se lève, marche et bouge. Bouger un peu vaut mieux que pas du tout, et plus apporte davantage."}$exo$::jsonb),
  ('3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, 1, 'redaction', $exo${"titre":"Elias, Bourdieu et les symboles","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Que veut dire Norbert Elias quand il parle d’un « **processus de civilisation** » à propos du sport ? Illustre avec un exemple.\n2. Qu’a montré Pierre Bourdieu en **1978** ? Cite deux sports plutôt liés aux classes aisées et deux plutôt liés aux classes populaires.\n3. Cite deux symboles d’**identité nationale** dans le sport, et deux drames qui ont marqué l’histoire des supporters.","bareme":[{"critere":"Elias : la violence est peu à peu contrôlée, le sport la canalise ; exemple du rugby réglementé avec un arbitre","points":6},{"critere":"Bourdieu (1978) : les pratiques se distribuent selon les classes sociales ; golf, tennis, équitation / boxe, football","points":7},{"critere":"Deux symboles (hymnes, haka, deux étoiles) et deux drames (Heysel 1985, Hillsborough 1989)","points":7}],"dureeMin":8,"corrige":"1. Pour **Norbert Elias**, la violence a été peu à peu **contrôlée** au fil des siècles : c’est le **processus de civilisation**. Le sport **canalise la violence** : un match de **rugby** est violent mais **réglementé**, encadré par un **arbitre** ; on se bat sans se blesser gravement.\n\n2. En **1978**, **Pierre Bourdieu** a montré que les pratiques sportives se **distribuent selon les classes sociales**. Plutôt aisées : **golf, tennis, équitation**. Plutôt populaires : **boxe, football**. Le choix d’un sport dit quelque chose du milieu (coût, lieux, codes).\n\n3. Symboles d’identité : les **hymnes**, le **haka** des All Blacks, les **deux étoiles** des Bleus après 1998 et 2018. Drames : le **Heysel** (**1985**, Belgique) et **Hillsborough** (**1989**, Angleterre), qui ont conduit à renforcer la sécurité dans les stades."}$exo$::jsonb),
  ('3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, 2, 'redaction', $exo${"titre":"Lecture d’un stade","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Voici un extrait d’article imaginé : *« Samedi, 60 000 spectateurs ont chanté l’hymne avant le match de rugby. Des supporters ultras ont animé les tribunes ; à la sortie, une minorité a provoqué des bagarres. Dans le quartier voisin, le club de boxe n’a pas de salle correcte, alors que le golf de la ville voisine refuse les inscriptions faute de place. »*\n\n1. Quels éléments illustrent le sport comme **institution**, **économie** et **discours** ? Donne un exemple pour chacun.\n2. Explique la scène du match avec **Elias** (violence canalisée) puis la scène du quartier avec **Bourdieu**. Cette lecture de 1978 est-elle encore pleinement valable ?\n3. Propose deux mesures pour limiter la violence des supporters et dis pourquoi le **Heysel** et **Hillsborough** sont des références.","bareme":[{"critere":"Institution (règles, fédérations), économie (billetterie, droits télé, équipementiers) et discours (valeurs d’effort, de mérite) illustrés","points":6},{"critere":"Elias appliqué au match réglementé ; Bourdieu appliqué au clivage boxe / golf ; nuance : lecture ancienne et discutée, les pratiques ont évolué","points":8},{"critere":"Deux mesures de sécurité cohérentes ; Heysel (1985) et Hillsborough (1989) comme drames ayant renforcé la sécurité","points":6}],"dureeMin":12,"corrige":"1. **Institution** : le sport a des règles et des fédérations (l’arbitre, le règlement du rugby). **Économie** : billetterie, droits télé, équipementiers (60 000 spectateurs payants). **Discours** : les valeurs qu’on lui attribue, effort, mérite, dépassement.\n\n2. Pour **Elias**, le match est violent mais **réglementé** : la violence est **canalisée**, et c’est la hors-stade qui échappe au cadre. Pour **Bourdieu (1978)**, le choix du sport dépend de la **classe sociale** (boxe populaire, golf des classes aisées, avec leurs coûts et leurs codes). Cette lecture est **ancienne et discutée** : les pratiques ont évolué, mais elle reste une **grille** pour comprendre les inégalités d’accès.\n\n3. Mesures : renforcer la **sécurité** et l’encadrement des tribunes, séparer les groupes de supporters, sanctionner les débordements. Le **Heysel** (**1985**, Belgique) et **Hillsborough** (**1989**, Angleterre) sont des drames qui ont conduit à **renforcer la sécurité dans les stades**."}$exo$::jsonb),
  ('3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, 3, 'redaction', $exo${"titre":"Le sport, miroir de la société ?","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Une affirmation : « Le sport est un monde à part, neutre et pur, où seuls comptent l’effort et le talent. La société n’y entre pas. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- montre que le sport est au contraire un **miroir** de la société, en mobilisant **Elias**, **Bourdieu** et au moins deux exemples d’**identité** ou de **supporters** ;\n- traite l’**inclusion** : Jeux paralympiques (Stoke Mandeville 1948, Rome 1960), place des femmes, débat sur le **hijab** et la laïcité en 2023-2024 ;\n- évoque le **dopage** et l’**environnement** (neige artificielle, déplacements) comme preuves de tensions ;\n- conclus en nuançant.","bareme":[{"critere":"Thèse du miroir démontrée avec Elias (violence canalisée) et Bourdieu (1978, classes sociales)","points":5},{"critere":"Identité et supporters : hymnes, haka, deux étoiles, ultras, Heysel 1985, Hillsborough 1989","points":4},{"critere":"Inclusion : Stoke Mandeville 1948, Rome 1960, femmes, débat sur le hijab 2023-2024 ; dopage et environnement évoqués","points":7},{"critere":"Conclusion nuancée et qualité de la rédaction","points":4}],"dureeMin":15,"corrige":"**Introduction.** Le sport n’est pas un monde à part : c’est un **miroir de la société**, avec ses fiertés, ses inégalités et ses tensions. Les sociologues l’étudient comme une **institution**, une **économie** et un **discours**.\n\n**Deux grilles sociologiques.** **Norbert Elias** voit dans le sport une image du **processus de civilisation** : la violence est **canalisée** par des règles et un arbitre (le rugby est dur mais réglementé). **Pierre Bourdieu**, en **1978**, a montré que les sports se distribuent selon les **classes sociales** : golf, tennis, équitation d’un côté, boxe et football de l’autre. La lecture est ancienne et discutée, mais elle montre que les inégalités entrent dans le stade.\n\n**Identité et supporters.** Les **hymnes**, le **haka** des All Blacks, les **deux étoiles** des Bleus (1998 et 2018) fabriquent du collectif et de l’appartenance. Les **ultras** animent les tribunes mais une minorité dérape : le **Heysel (1985)** et **Hillsborough (1989)** ont conduit à renforcer la sécurité.\n\n**Inclusion et débats.** Les **Jeux paralympiques** sont nés à **Stoke Mandeville** en **1948** pour des blessés de guerre ; la première édition officielle a eu lieu à **Rome en 1960**. Le sport peut faire progresser l’égalité entre femmes et hommes, même si les femmes ont longtemps été exclues de nombreuses disciplines. En **2023-2024**, le port du **hijab** en compétition a nourri un débat sur la **laïcité** et l’égalité d’accès au sport, avec des positions différentes selon les fédérations.\n\n**Tensions.** L’olympisme est un idéal mais aussi une **vitrine** ; le **dopage** est un **symptôme de la pression à gagner**. La **neige artificielle** et les **déplacements** montrent l’empreinte écologique.\n\n**Conclusion.** Le sport reflète la société mais peut aussi la faire évoluer (inclusion, règles) : un miroir, pas une copie conforme."}$exo$::jsonb),
  ('0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, 1, 'redaction', $exo${"titre":"Valeurs et chiffres de Paris 2024","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Quel texte fixe les principes du mouvement olympique ? Nomme les **trois valeurs** olympiques.\n2. Qu’est-ce que la **trêve olympique** et que veut faire l’**Agenda 2020** du CIO ?\n3. Donne **trois chiffres ou faits** sur Paris 2024.","bareme":[{"critere":"Charte olympique et trois valeurs : excellence, amitié, respect","points":6},{"critere":"Trêve olympique (suspendre les conflits, résolution de l’ONU) et Agenda 2020 (Jeux moins chers, sites existants)","points":7},{"critere":"Trois faits exacts : environ 95 % de sites existants ou temporaires, environ 10 500 athlètes, parité, billetterie paralympique record","points":7}],"dureeMin":8,"corrige":"1. La **Charte olympique** fixe les principes du mouvement olympique. Ses trois valeurs sont l’**excellence**, l’**amitié** et le **respect**.\n\n2. La **trêve olympique**, appuyée par une **résolution de l’ONU**, appelle à **suspendre les conflits** pendant les Jeux (son application reste incertaine). L’**Agenda 2020** du CIO veut des Jeux **moins chers**, qui **réutilisent des sites existants** plutôt que de tout construire.\n\n3. Paris 2024 : environ **95 % de sites existants ou temporaires**, environ **10 500 athlètes**, la **parité** (autant de places pour les femmes que pour les hommes), un **record** de billetterie paralympique (il suffit d’en donner trois)."}$exo$::jsonb),
  ('0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, 2, 'redaction', $exo${"titre":"Un héritage à évaluer","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Voici un tableau d’héritage imaginé après les Jeux de Paris :\n\n| Équipement | Situation |\n| Village olympique | devenu quartier de logements à Saint-Denis, Saint-Ouen et L’Île-Saint-Denis |\n| Seine | baignade rendue au public en 2025 après de gros travaux |\n| Centre aquatique de Saint-Denis | ouvert aux habitants et aux clubs |\n| Mesures de sécurité | très lourdes pendant les Jeux |\n| Personnes vivant en précarité | des délogements signalés avant les Jeux |\n\n1. Classe chaque ligne : **bénéfice durable** ou **controverse**.\n2. Explique pourquoi la part de **sites existants** (95 %) fait partie de la logique d’**héritage**.\n3. Pour un habitant de Saint-Denis, quels critères retiendrais-tu pour juger si les Jeux ont été réussis ? Argumente en citant un bénéfice et une critique.","bareme":[{"critere":"Classement correct : village, Seine et centre aquatique = bénéfices ; sécurité et délogements = controverses","points":7},{"critere":"Lien entre sites existants ou temporaires, Agenda 2020 et héritage : on ne construit que ce dont on se servira ensuite","points":6},{"critere":"Critères argumentés (coût, valeurs, équipements laissés, image) avec un bénéfice ET une critique","points":7}],"dureeMin":12,"corrige":"1. **Bénéfices durables** : le **village olympique** devenu quartier de logements, la **Seine** rendue à la baignade (2025), le **centre aquatique de Saint-Denis** ouvert aux habitants et aux clubs. **Controverses** : les mesures de **sécurité** très lourdes et les **délogements** de personnes en précarité (le **coût** reste aussi une critique).\n\n2. Avec **95 % de sites existants ou temporaires**, Paris applique l’**Agenda 2020** : un **bon héritage se prépare avant les Jeux**, on ne construit que ce dont on se servira ensuite. Cela réduit le coût et évite les équipements abandonnés.\n\n3. Critères : le **coût** et qui paie, les **équipements** laissés aux habitants, le respect des **valeurs** (excellence, amitié, respect), l’image du pays. Exemple : bénéfice, le centre aquatique ouvert aux habitants ; critique, les délogements avant les Jeux. Une réflexion solide cite **bénéfices ET critiques**, appuyés sur des faits."}$exo$::jsonb),
  ('0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, 3, 'redaction', $exo${"titre":"Les Jeux, idéal ou vitrine ?","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un journaliste écrit : « Les Jeux olympiques ne sont qu’une opération commerciale et politique. L’idéal olympique est un mythe : aucun héritage réel ne reste après la flamme. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- discute cette thèse en présentant l’**idéal** (Charte, trois valeurs, trêve) et la **réalité** (vitrine, coût, sécurité, délogements) ;\n- évalue l’**héritage de Paris 2024** à l’aide de faits précis (chiffres, Seine, village, centre aquatique, piscines) ;\n- explique le rôle de l’**Agenda 2020** ;\n- ouvre sur la suite (**Milan-Cortina 2026**, **Los Angeles 2028**, **Alpes françaises 2030**) et conclus.","bareme":[{"critere":"Idéal (Charte, excellence, amitié, respect, trêve de l’ONU) opposé à la réalité (vitrine politique et économique, coût, sécurité, délogements)","points":6},{"critere":"Héritage de Paris 2024 évalué avec faits précis (95 %, 10 500 athlètes, parité, Seine 2025, village, centre aquatique, piscines)","points":6},{"critere":"Agenda 2020 expliqué ; ouverture sur les Jeux suivants sans citer de résultat","points":4},{"critere":"Conclusion nuancée et qualité de la rédaction","points":4}],"dureeMin":15,"corrige":"**Introduction.** Le journaliste a raison sur un point : les Jeux sont une **vitrine** politique et économique. Mais affirmer qu’aucun héritage ne reste va trop loin.\n\n**L’idéal.** La **Charte olympique** fixe les principes du mouvement et trois valeurs : **excellence**, **amitié** et **respect**. La **trêve olympique**, appuyée par une **résolution de l’ONU**, appelle à suspendre les conflits ; son application est incertaine, mais l’idée reste puissante.\n\n**La réalité et les critiques.** Un événement de cette taille suscite des critiques : le **coût** et la question de qui paie, des mesures de **sécurité** très lourdes, des **délogements** de personnes en précarité signalés avant les Jeux.\n\n**Un héritage mesurable.** Face à des Jeux de plus en plus coûteux, le CIO a adopté l’**Agenda 2020** : Jeux **moins chers**, **sites existants** réutilisés. Paris 2024 a utilisé environ **95 % de sites existants ou temporaires**, accueilli environ **10 500 athlètes**, avec la **parité** et un **record** de billetterie paralympique. Concrètement : la **Seine** a été rendue à la baignade (**2025**) après de gros travaux, le **village olympique** est devenu un **quartier de logements** (Saint-Denis, Saint-Ouen, L’Île-Saint-Denis), le **centre aquatique de Saint-Denis** est ouvert aux habitants et aux clubs, des **piscines** de quartier ont été créées ou rénovées.\n\n**La suite.** **Milan-Cortina 2026**, **Los Angeles 2028** et les **Alpes françaises 2030** devront chacune répondre à la même question d’héritage.\n\n**Conclusion.** Les Jeux sont à la fois idéal et vitrine : leur bilan se juge sur des faits, bénéfices comme critiques. Un héritage se prépare avant les Jeux, et il reste après la flamme."}$exo$::jsonb),
  ('7f3a9119-5afb-5151-889c-23f358b712dd'::uuid, 1, 'redaction', $exo${"titre":"La licence STAPS","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Que signifie **STAPS** ? Cite **trois des cinq mentions** de la licence.\n2. Quels sont, sur **Parcoursup**, les trois champs d’attentes pour la filière ?\n3. Quels diplômes du ministère des Sports permettent d’entraîner (du plus bas au plus haut) ? Comment devient-on professeur d’EPS ?","bareme":[{"critere":"STAPS : sciences et techniques des activités physiques et sportives ; trois mentions exactes","points":6},{"critere":"Trois champs d’attentes : sciences, expression (écrit, oral), pratique sportive","points":6},{"critere":"BPJEPS, DEJEPS, DESJEPS ; professeur d’EPS : master MEEF puis concours du CAPEPS","points":8}],"dureeMin":7,"corrige":"1. **STAPS** signifie **sciences et techniques des activités physiques et sportives**. Cinq mentions : **entraînement sportif**, **activité physique adaptée et santé**, **éducation et motricité**, **management du sport**, **ergonomie du sport et performance motrice** (il suffit d’en citer trois).\n\n2. Les attentes portent sur les **sciences** (biologie, physique), l’**expression** (écrit et oral) et la **pratique** sportive : il ne suffit pas d’être sportif.\n\n3. Le ministère des Sports délivre le **BPJEPS**, le **DEJEPS** et le **DESJEPS**, de plus en plus élevés, pour animer, entraîner et diriger. Pour devenir professeur d’EPS, on passe par un **master MEEF**, puis on prépare le **CAPEPS**, le concours qui mène au métier."}$exo$::jsonb),
  ('7f3a9119-5afb-5151-889c-23f358b712dd'::uuid, 2, 'redaction', $exo${"titre":"Trois élèves, trois voies","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Trois élèves de Terminale parlent de leur avenir :\n- **Inès** aime la biologie et aimerait accompagner des personnes âgées ou malades grâce au sport.\n- **Karim** rêve d’entraîner une équipe de jeunes mais n’aime pas écrire.\n- **Léa** adore l’organisation et l’événementiel et se verrait diriger un club ou un événement sportif.\n\n1. Pour chacun, propose une **mention STAPS** adaptée, un **métier** possible et, si besoin, un **diplôme** ou un concours.\n2. Karim craint que « le sport suffise ». Explique pourquoi c’est insuffisant pour la filière STAPS (Parcoursup).\n3. Cite deux autres **métiers** du sport (préparateur physique, analyste de données, journaliste, industrie…) et dis ce que fait chacun.","bareme":[{"critere":"Trois propositions cohérentes : Inès en APA et santé, Karim en entraînement sportif (BPJEPS à DESJEPS), Léa en management du sport","points":8},{"critere":"Sciences, expression et pratique : trois attentes Parcoursup, le sport seul ne suffit pas","points":6},{"critere":"Deux métiers supplémentaires décrits avec précision","points":6}],"dureeMin":12,"corrige":"1. **Inès** : mention **activité physique adaptée et santé**, métier d’enseignant en activité physique adaptée ou d’accompagnement de publics malades, âgés, handicapés (la voie du **kinésithérapeute** est aussi possible, mais l’accès varie selon les universités : PASS, LAS ou première année de STAPS, il faut vérifier). **Karim** : mention **entraînement sportif**, avec les diplômes du ministère des Sports (**BPJEPS**, **DEJEPS**, **DESJEPS**) pour entraîner. **Léa** : mention **management du sport**, métiers d’organisatrice d’événements ou de gestionnaire de club.\n\n2. Sur **Parcoursup**, la filière attend trois choses : des **sciences** (biologie, physique), de l’**expression** (écrit et oral) et de la **pratique** sportive. Karim devra donc aussi savoir écrire.\n\n3. Le **préparateur physique** construit la condition physique des sportifs ; l’**analyste de données** exploite les chiffres (GPS, capteurs, statistiques) pour éclairer les décisions de l’entraîneur. Le **journaliste sportif** raconte, analyse, filme ; l’**industrie** (équipementiers) conçoit chaussures, maillots et matériel (il suffit de deux)."}$exo$::jsonb),
  ('7f3a9119-5afb-5151-889c-23f358b712dd'::uuid, 3, 'redaction', $exo${"titre":"Vivre du sport sans être champion","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un lycéen dit : « Si je ne deviens pas sportif professionnel, je n’ai aucun avenir dans le sport. Et pour entrer en STAPS, il suffit d’être bon en sport. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- montre à partir de **cinq métiers** que le sport est un **vaste secteur d’emploi**, en formulant prudemment des ordres de grandeur ;\n- présente la **licence STAPS** (cinq mentions) et ses **attentes Parcoursup** ;\n- indique les voies d’accès à au moins **trois métiers** (professeur d’EPS, entraîneur, kinésithérapeute…), en restant prudent sur ce qui varie selon les universités ;\n- explique comment un **sportif de haut niveau** concilie études et entraînement, et conclus sur le choix d’orientation.","bareme":[{"critere":"Cinq métiers présentés et secteur d’emploi (plusieurs centaines de milliers d’emplois) formulé prudemment","points":5},{"critere":"Licence STAPS : cinq mentions justes et attentes Parcoursup (sciences, expression, pratique) pour contredire le « il suffit d’être bon en sport »","points":6},{"critere":"Voies d’accès exactes : master MEEF et CAPEPS, BPJEPS, DEJEPS, DESJEPS, kinésithérapie (PASS, LAS ou STAPS, à vérifier)","points":5},{"critere":"Sportif de haut niveau, aménagements scolaires, conclusion et qualité de la rédaction","points":4}],"dureeMin":15,"corrige":"**Introduction.** Ce lycéen se trompe deux fois : le sport offre bien plus de débouchés que le haut niveau, et la filière **STAPS** exige davantage que de bonnes performances.\n\n**Un vaste secteur d’emploi.** Le sport représente en France **plusieurs centaines de milliers d’emplois** (ordre de grandeur à formuler avec prudence) : enseignement, clubs, salles, événementiel, industrie, médias. Cinq portraits : le **professeur d’EPS**, l’**entraîneur**, le **kinésithérapeute**, le **préparateur physique** et l’**analyste de données** ; on peut ajouter l’organisateur d’événements, le journaliste sportif ou les métiers des équipementiers.\n\n**La licence STAPS.** Elle compte **cinq mentions** : entraînement sportif ; activité physique adaptée et santé ; éducation et motricité ; management du sport ; ergonomie du sport et performance motrice. Sur **Parcoursup**, les attentes portent sur les **sciences**, l’**expression** et la **pratique** : il ne suffit pas d’être bon en sport.\n\n**Les voies d’accès.** Professeur d’EPS : **master MEEF** puis **CAPEPS**. Entraîneur : **BPJEPS**, **DEJEPS**, **DESJEPS** du ministère des Sports. Kinésithérapeute : l’accès varie selon les universités (**PASS**, **LAS** ou première année de STAPS) : il faut **vérifier** auprès de l’établissement visé.\n\n**Le haut niveau.** Un jeune **sportif de haut niveau** peut bénéficier d’**aménagements scolaires** (horaires, examens, soutien), notamment via les pôles et sections, pour concilier études et entraînement.\n\n**Conclusion.** Choisir, c’est se demander ce que l’on aime faire, avec qui et dans quel cadre (terrain, bureau, hôpital), puis remonter du métier vers la formation, en vérifiant toujours les conditions d’accès officielles."}$exo$::jsonb),
  ('8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 1, 'redaction', $exo${"titre":"Les règles du bac d’EPS","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Comment l’EPS est-elle évaluée au bac (mode d’évaluation, nombre d’épreuves, champs d’apprentissage) et quel est son **coefficient** ?\n2. Nomme les trois **AFL** et donne le nombre de points de l’**AFL1**.\n3. Que se passe-t-il en cas d’**absence non justifiée** à une épreuve ?","bareme":[{"critere":"CCF en Terminale, trois épreuves sur trois activités de trois champs différents, coefficient 6","points":7},{"critere":"AFL1 (agir, performer, être efficace), AFL2 (s’entraîner, se préparer, analyser), AFL3 (tenir des rôles) ; AFL1 = 12 points","points":7},{"critere":"Absence non justifiée : note de 0 à l’épreuve, non éliminatoire mais la moyenne chute","points":6}],"dureeMin":7,"corrige":"1. L’évaluation se fait en **contrôle en cours de formation (CCF)**, pendant l’année de Terminale. Il y a **trois épreuves** sur **trois activités distinctes**, issues de **trois champs d’apprentissage différents**. Le **coefficient** est **6**. La note finale est la moyenne des trois épreuves.\n\n2. **AFL1** : agir, performer, être efficace ; **AFL2** : s’entraîner, se préparer, analyser ; **AFL3** : tenir des rôles. L’**AFL1 vaut 12 points** sur 20, évalués le jour de l’épreuve.\n\n3. Une absence **non justifiée** vaut **0** à cette épreuve : ce n’est pas éliminatoire, mais cela fait chuter la moyenne."}$exo$::jsonb),
  ('8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 2, 'redaction', $exo${"titre":"Le dossier de Samir","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Samir passe ses trois épreuves de bac en EPS : *15/20 en natation (CA1), 11/20 en acrosport (CA3) et il a manqué la rencontre de badminton (CA4) sans justificatif.* Dans la séquence de badminton, il avait choisi **4 points pour l’AFL2 et 4 pour l’AFL3**, mais il oubliait son carnet et n’arbitrait presque jamais.\n\n1. Calcule sa **note finale** d’EPS. Que changerait un certificat médical attestant une blessure ?\n2. Rappelle comment sont répartis les **20 points** d’une épreuve et quelles répartitions Samir pouvait choisir pour les AFL2 et AFL3.\n3. Explique pourquoi sa préparation pendant la séquence compte autant que le jour de l’épreuve, et donne-lui deux conseils pour sa prochaine séquence.","bareme":[{"critere":"Moyenne (15 + 11 + 0) / 3 ≈ 8,7 sur 20 (arrondie à 9 après harmonisation) ; avec un justificatif : épreuve adaptée ou différée","points":7},{"critere":"AFL1 = 12 points, AFL2 + AFL3 = 8 points partagés ; répartitions 4/4, 6/2 ou 2/6","points":6},{"critere":"AFL2 et AFL3 se gagnent pendant la séquence (carnet régulier, rôle assumé) ; deux conseils concrets","points":7}],"dureeMin":12,"corrige":"1. La note est la **moyenne des trois épreuves** : (15 + 11 + 0) / 3 ≈ **8,7**, soit environ **9/20** après arrondi au point entier. L’absence non justifiée vaut **0**. Avec un **certificat médical** attestant une blessure ou un problème de santé temporaire, il aurait droit à une **épreuve adaptée ou différée** au lieu du 0.\n\n2. L’**AFL1** vaut **12 points** (le jour de l’épreuve). Les **8 points restants** sont partagés entre l’**AFL2** et l’**AFL3** : l’élève choisit **4/4** (équilibré), **6/2** (priorité à l’entraînement) ou **2/6** (priorité aux rôles).\n\n3. L’AFL2 et l’AFL3 se gagnent **au fil de la séquence**, pas seulement le jour de l’épreuve : un **carnet tenu régulièrement** et un **rôle assumé à chaque séance** valent des points. Conseils : tenir son carnet à chaque séance (AFL2) et prendre un rôle (arbitre, coach, observateur) à chaque séance (AFL3), et s’assurer de justifier toute absence."}$exo$::jsonb),
  ('8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 3, 'redaction', $exo${"titre":"Stratégie pour le bac d’EPS","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Un élève de Terminale explique : « Au bac d’EPS, seul compte le jour de l’épreuve : il suffit d’être fort physiquement. Les rôles et le carnet, c’est du bonus que l’on peut ignorer, et mieux vaut choisir les trois mêmes types d’activités. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- corrige ces erreurs en présentant le cadre (CCF, trois épreuves, champs différents, activités nationales et académiques, co-évaluation, coefficient 6) ;\n- explique les **trois AFL** et la **répartition des points** (12 + 8) et le choix possible pour l’AFL2 et l’AFL3 ;\n- montre comment une **stratégie** (choix des activités, choix de la répartition, carnet, rôles) maximise la note ;\n- explique les cas particuliers (absence, blessure, candidats individuels) et conclus.","bareme":[{"critere":"Cadre exact : CCF en Terminale, trois épreuves de champs différents, deux activités nationales au moins, co-évaluation, coefficient 6","points":5},{"critere":"Trois AFL expliqués, 12 points pour l’AFL1 et 8 points partagés ; répartitions 4/4, 6/2, 2/6 argumentées","points":6},{"critere":"Stratégie cohérente : activités variées, carnet et rôles pendant la séquence, choix de la répartition adapté à son profil","points":5},{"critere":"Cas particuliers (absence = 0, épreuve adaptée, ponctuel terminal) et qualité de la rédaction","points":4}],"dureeMin":15,"corrige":"**Introduction.** Cet élève se trompe : le bac d’EPS ne récompense pas seulement la force le jour J, il évalue une **démarche** menée tout au long de la Terminale.\n\n**Le cadre.** L’EPS est évaluée en **contrôle en cours de formation (CCF)** pendant l’année de Terminale : **trois épreuves** sur **trois activités distinctes** issues de **trois champs d’apprentissage différents**, dont au moins **deux** de la liste nationale (la troisième peut venir de la liste académique ou de l’établissement). Chaque épreuve est notée sur 20, évaluée par **deux enseignants** (co-évaluation), et la note finale est la **moyenne des trois**. Le **coefficient** est **6**. Les règles viennent de la note de service du 20 février 2026.\n\n**Les trois AFL.** L’**AFL1** (agir, performer, être efficace) vaut **12 points**, le jour de l’épreuve. L’**AFL2** (s’entraîner, se préparer, analyser) et l’**AFL3** (tenir des rôles) se partagent **8 points**, que l’élève **répartit** : 4/4, 6/2 ou 2/6. Ils se gagnent **pendant la séquence** : carnet régulier, rôle assumé (arbitre, coach, observateur).\n\n**Une stratégie.** Choisir des activités où l’on est à l’aise dans trois champs, répartir les 8 points selon son profil (un élève régulier qui arbitre bien prend 6 points sur l’AFL3 : une rencontre ratée pèse moins), et préparer son carnet séance après séance. Exemple : 14, 16 et 12 donnent une moyenne de 14/20.\n\n**Les pièges.** Une **absence non justifiée** vaut **0** (non éliminatoire, mais la moyenne chute) ; une blessure attestée ouvre droit à une **épreuve adaptée ou différée** ; l’évaluation ne repose jamais sur les seuls AFL2 et AFL3. Les candidats individuels et ceux du Cned passent un **examen ponctuel terminal** sur deux activités.\n\n**Conclusion.** Le bac d’EPS se prépare toute l’année : les points sont dans la régularité autant que dans la performance."}$exo$::jsonb),
  ('f16056b9-301c-5bcd-8db0-72e8c31a1dbb'::uuid, 1, 'redaction', $exo${"titre":"Option et spécialité","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Décris l’**option EPS** : durée, horaire hebdomadaire, but et mode d’évaluation.\n2. Décris la **spécialité EPPCS** : date de création, horaires en 1re et en Tle, forme de l’épreuve terminale.\n3. Cite **trois savoirs** étudiés en EPPCS.","bareme":[{"critere":"Option EPS : de la 2de à la Tle, 3 heures par semaine, programme de 2019, approfondir la pratique et réfléchir, contrôle continu","points":7},{"critere":"EPPCS : créée en 2021, 4 h en 1re, 6 h en Tle, épreuve avec un écrit et une partie pratique","points":7},{"critere":"Trois savoirs : sciences du sport, histoire, sociologie, projet collectif","points":6}],"dureeMin":7,"corrige":"1. L’**option EPS** s’étend de la **2de à la Tle**, à raison de **3 heures par semaine**, selon un programme de **2019**. Son but : **approfondir la pratique** et **réfléchir sur le sport**. Elle compte en **contrôle continu**.\n\n2. La spécialité **EPPCS** (Éducation physique, pratiques et culture sportives) a été créée en **2021**. Elle compte **4 heures par semaine en 1re** et **6 heures en Tle**, avec une épreuve terminale composée d’un **écrit** et d’une **partie pratique**.\n\n3. En EPPCS, on étudie les **sciences du sport** (physiologie, entraînement, biomécanique), l’**histoire** du sport, la **sociologie** (le sport dans la société, inégalités, identités) et un **projet collectif** (il suffit d’en citer trois)."}$exo$::jsonb),
  ('f16056b9-301c-5bcd-8db0-72e8c31a1dbb'::uuid, 2, 'redaction', $exo${"titre":"Est-ce pour moi ?","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Trois élèves de 2de hésitent :\n- **Hugo** adore pratiquer son sport, veut s’entraîner plus et ne souhaite pas de cours théoriques.\n- **Sana** veut devenir kinésithérapeute ou entrer en STAPS, aime écrire et travailler en projet.\n- **Yanis** est sportif de haut niveau en pôle espoirs et a des horaires d’entraînement chargés.\n\n1. Pour chacun, propose le dispositif le plus adapté (EPS commune, **option EPS**, **spécialité EPPCS**, **sport-études / pôle espoirs / aménagements**) et justifie.\n2. Explique pourquoi l’EPPCS n’est pas « un cours de sport en plus ».\n3. Cite deux structures qui aident à concilier sport et études et dis comment l’EPPCS peut servir au **Grand oral**.","bareme":[{"critere":"Trois propositions justifiées : Hugo option EPS, Sana EPPCS, Yanis aménagements et sport-études","points":9},{"critere":"EPPCS = vraie matière de culture : écrit, notions à maîtriser, sciences, histoire, sociologie, projet","points":5},{"critere":"Deux structures (sections sportives, pôles espoirs, sport-études, aménagements) et lien avec le Grand oral (sujet sur récupération, olympisme, santé publique)","points":6}],"dureeMin":12,"corrige":"1. **Hugo** : l’**option EPS** (3 h par semaine, plus de pratique et un peu de réflexion, en contrôle continu). **Sana** : la **spécialité EPPCS**, qui mène vers STAPS ou la kinésithérapie, avec écrit, sciences et projet. **Yanis** : les structures de haut niveau (**pôle espoirs**, **sport-études**, **aménagements** d’horaires et d’examens) qui organisent sa scolarité autour des entraînements.\n\n2. L’EPPCS demande de travailler **comme dans une matière théorique** : il y a de l’**écrit** (épreuve terminale avec écrit et partie pratique) et des **notions** à maîtriser (sciences du sport, histoire, sociologie), plus un projet collectif. Ce n’est pas du sport en plus.\n\n3. Structures : les **sections sportives scolaires** (s’entraîner davantage pendant les heures de classe) et les **pôles espoirs** (jeunes à fort potentiel) ; aussi le **sport-études** et les **aménagements** pour sportif de haut niveau. Au **Grand oral**, l’EPPCS donne un point d’appui : un sujet sur la **récupération**, l’**olympisme** ou la **santé publique** devient un terrain naturel."}$exo$::jsonb),
  ('f16056b9-301c-5bcd-8db0-72e8c31a1dbb'::uuid, 3, 'redaction', $exo${"titre":"Choisir son parcours sportif au lycée","consigne":"Rédige une réponse argumentée, organisée et appuyée sur des notions du cours.","enonce":"*Une élève dit : « L’option EPS et l’EPPCS, c’est pareil : du sport en plus. Il suffit d’aimer jouer pour réussir, et les sections sportives ou le sport-études ne servent à rien pour les études. »*\n\nRédige un texte argumenté d’environ vingt lignes :\n- compare l’**option EPS** et la **spécialité EPPCS** (durée, horaires, programme, évaluation, contenus) pour réfuter l’idée qu’elles sont identiques ;\n- explique pour **quel profil** chacune est faite et à quelles études elle prépare (STAPS, kinésithérapie, éducation, management du sport) ;\n- présente les **structures** (sections sportives, pôles espoirs, sport-études, aménagements pour sportif de haut niveau) ;\n- explique le lien avec le **Grand oral** et avec les contenus des autres fiches (périodisation, récupération, olympisme, santé publique) puis conclus.","bareme":[{"critere":"Comparaison exacte option EPS (2de à Tle, 3 h, programme 2019, contrôle continu) / EPPCS (créée en 2021, 4 h en 1re, 6 h en Tle, écrit et pratique)","points":7},{"critere":"Profils et poursuites d’études justifiés, nécessité du travail écrit et de notions théoriques en EPPCS","points":5},{"critere":"Structures présentées avec leur utilité ; lien avec le Grand oral et les autres fiches","points":5},{"critere":"Conclusion nuancée et qualité de la rédaction","points":3}],"dureeMin":15,"corrige":"**Introduction.** L’option EPS et la spécialité EPPCS ne sont pas deux versions d’un même cours : leur ambition, leur volume et leur évaluation diffèrent beaucoup.\n\n**Deux dispositifs distincts.** L’**option EPS** court de la **2de à la Tle**, à raison de **3 heures par semaine**, selon un programme de **2019** : **approfondir la pratique** et **réfléchir sur le sport**, avec une évaluation en **contrôle continu**. La spécialité **EPPCS**, créée en **2021**, est une spécialité à part entière : **4 heures en 1re**, **6 heures en Tle**, avec une épreuve terminale composée d’un **écrit** et d’une **partie pratique**. On y étudie les **sciences du sport**, l’**histoire**, la **sociologie** et un **projet collectif**.\n\n**Pour quel profil ?** L’option convient à qui veut pratiquer davantage tout en réfléchissant un peu. L’EPPCS s’adresse à ceux qui aiment **à la fois pratiquer et réfléchir**, et qui visent souvent **STAPS**, la **kinésithérapie**, l’éducation ou le management du sport. Elle demande d’aimer écrire autant que courir ; il faut consulter le programme officiel et demander conseil à ses professeurs.\n\n**Les structures autour du sport.** Les **sections sportives scolaires** permettent de s’entraîner davantage pendant les heures de classe ; les **pôles espoirs** accueillent des jeunes à fort potentiel ; le **sport-études** organise une scolarité adaptée aux entraînements ; les **aménagements** pour sportif de haut niveau (horaires, examens) concilient études et carrière. Elles servent donc aux études.\n\n**Le Grand oral.** Avec l’EPPCS, une spécialité sportive devient un point d’appui : récupération, périodisation, olympisme, santé publique sont des sujets naturels, traités avec des faits et un regard critique.\n\n**Conclusion.** Chacun choisira selon ses goûts et ses projets : l’EPS commune, l’option ou la spécialité, avec ses structures d’appui."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
   WHERE e.origine = 'catalogue'
     AND e.chapter_id IN ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f', 'c8ffe450-41cc-5f3c-860d-ee330d92b067', '58518308-9b83-5a9a-9ea1-7dd3909ab86b', '3e6141f6-e362-5765-a122-b8532787e93a', '475d747d-a507-5860-ad09-00a4423612c4', '3a645063-6988-5233-bf5f-1c89d6ccd46d', '0c7e3352-9d7e-5927-9560-c4de48d50b67', '7f3a9119-5afb-5151-889c-23f358b712dd', '8561efa6-7303-530e-a51d-a4b84b1ef822', 'f16056b9-301c-5bcd-8db0-72e8c31a1dbb');
  RAISE NOTICE '575 : % sujets au catalogue (attendu : 30)', n;
  IF n < 30 THEN
    RAISE WARNING '575 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
